function seed(){const clients=[{id:'CL-001',name:'Example Trading Entity',initials:'ET',color:'',industry:'Trading & distribution',contact:'Omar Nasser',risk:'Moderate',status:'Active',country:'Demo jurisdiction',revenue:600000}, {id:'CL-002',name:'Northstar Services',initials:'NS',color:'purple',industry:'Professional services',contact:'Aisha Saleh',risk:'Low',status:'Active',country:'Demo jurisdiction',revenue:1800000}, {id:'CL-003',name:'Cedar Manufacturing',initials:'CM',color:'blue',industry:'Manufacturing',contact:'Noah Williams',risk:'Moderate',status:'Active',country:'Demo jurisdiction',revenue:2400000}, {id:'CL-004',name:'Harbor Logistics',initials:'HL',color:'amber',industry:'Transport & logistics',contact:'Riya Ahmed',risk:'Low',status:'Active',country:'Demo jurisdiction',revenue:1200000}];
 const engs=[newEng('ENG-26001','CL-001'),newEng('ENG-26002','CL-002','Annual accounts','Accounting',3),newEng('ENG-26003','CL-003','External audit','Fieldwork',4),newEng('ENG-26004','CL-004','Internal audit','Planning',2)];
 engs[1].eqrRequired=false;engs[1].reviews=engs[1].reviews.slice(0,1);engs[1].workpapers=engs[1].workpapers.slice(0,3);engs[2].reviews=engs[2].reviews.slice(0,1);engs[3].reviews=[];engs[3].eqrRequired=false;engs[3].workpapers=engs[3].workpapers.map(w=>({...w,status:'Planned'}));
 return {schema:SCHEMA,selected:'ENG-26001',role:'manager',clients,engagements:engs,leads:[{id:'LD-001',name:'Aspen Retail',contact:'Mira Thomas',service:'Annual accounts',value:850000,stage:'Inquiry',accepted:false,terms:false},{id:'LD-002',name:'Summit Engineering',contact:'Zayd Hasan',service:'External audit',value:1400000,stage:'Discovery',accepted:false,terms:false},{id:'LD-003',name:'Orchid Hospitality',contact:'Lena James',service:'External audit',value:1800000,stage:'Evaluation',accepted:false,terms:false},{id:'LD-004',name:'Atlas Technology',contact:'Hana Ali',service:'Internal audit',value:1200000,stage:'Proposal',accepted:true,terms:false}],invoices:[{id:'INV-26001',client:'CL-001',eng:'ENG-26001',description:'Annual audit · first milestone',amount:600000,paid:0,status:'Issued',due:'2026-09-28'},{id:'INV-26002',client:'CL-002',eng:'ENG-26002',description:'Annual accounts · final milestone',amount:850000,paid:850000,status:'Paid',due:'2026-09-18'},{id:'INV-26003',client:'CL-003',eng:'ENG-26003',description:'Financial audit · retainer',amount:900000,paid:0,status:'Draft',due:'2026-10-01'}],times:[{name:'Adam Khan',task:'Fixed-asset workpaper',hours:3,eng:'ENG-26001',date:DEMO_DATE}],events:[{text:'Financial package v3 prepared for review',ref:'ENG-26001',time:'Sample · 09:40',type:'file'},{text:'Sara raised a depreciation review point',ref:'RN-001',time:'Sample · 09:20',type:'message'},{text:'Trial balance accepted and mapped',ref:'ENG-26001',time:'Sample · 08:45',type:'checkcircle'}]};}
let state, persist=true;
try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?JSON.parse(raw):seed();if(state.schema!==SCHEMA||!Array.isArray(state.engagements)||!Array.isArray(state.clients))state=seed();}catch{state=seed();persist=false;}
