function clients(){const list=state.clients.filter(c=>(c.name+' '+c.industry).toLowerCase().includes(ui.clientFilter.toLowerCase()));return head('Client portfolio','Separate relationships, legal entities and engagement responsibilities.',btn('Add client via acquisition','new-lead','primary','','plus'))+`<div class="toolbar"><div class="input-search">${icon('search')}<input class="input" id="client-filter" value="${esc(ui.clientFilter)}" placeholder="Find a client or industry" aria-label="Filter clients"></div><span class="tag gray">${list.length} sample clients</span></div><div class="grid3">${list.map(c=>{const es=state.engagements.filter(e=>e.client===c.id);return `<section class="client-card"><div class="between">${avatar(c.initials,c.color,'square')}${badge(c.status)}</div><h3>${esc(c.name)}</h3><p class="sub">${esc(c.industry)}</p><div class="row mt12"><span class="caption">${c.id}</span>${badge(c.risk+' risk',c.risk==='Low'?'green':'amber')}</div><div class="clientstats"><div><small>Engagements</small><b>${es.length}</b></div><div><small>Relationship contact</small><span class="small">${esc(c.contact)}</span></div></div><div class="between mt20"><button class="textlink" data-action="client-detail" data-id="${c.id}">Client 360</button>${btn('Open workspace','eng-open','sm',`data-id="${es[0]?.id||''}"`,'arrow')}</div></section>`;}).join('')}</div>${note('These are synthetic legal entities. A relationship may contain several entities; this demo keeps them separate and links work by explicit engagement ID.','', '').replace('class="banner ','class="banner mt24 ')}${footer('DAT-01–04 · LC-07')}`;}
function acquisition(){const cols=['Inquiry','Discovery','Evaluation','Proposal'];return head('From first conversation to trusted client.','Qualify opportunities without confusing commercial interest with professional acceptance.',btn('New inquiry','new-lead','primary','','plus'))+`<div class="metric-grid">${metric('Open opportunities',state.leads.filter(l=>l.stage!=='Converted').length,'Synthetic commercial pipeline','target')}${metric('Illustrative fee pipeline',cash(state.leads.filter(l=>l.stage!=='Converted').reduce((s,l)=>s+l.value,0)),'Proposed fees, not posted revenue','chart','purple')}${metric('Acceptance required',state.leads.filter(l=>!l.accepted).length,'A proposal does not authorize work','shield','amber')}${metric('Converted',state.leads.filter(l=>l.stage==='Converted').length,'Terms and demo acceptance recorded','checkcircle','blue')}</div><div class="kanban">${cols.map((col,i)=>`<section class="kanban-col"><div class="kanban-title"><span>${col}</span><span class="tag gray">${state.leads.filter(l=>l.stage===col).length}</span></div>${state.leads.filter(l=>l.stage===col).map(l=>`<button class="lead-card" data-action="lead-detail" data-id="${l.id}">${badge(l.service,i%2?'purple':'blue')}<h3>${esc(l.name)}</h3><p>${esc(l.contact)} · ${l.id}</p><div class="value">${cash(l.value)}</div><div class="between mt12"><span class="caption">${l.accepted?'Acceptance recorded':'Acceptance pending'}</span>${avatar('LR','purple','sm')}</div></button>`).join('')}<button class="kanban-add" data-action="new-lead">+ Add opportunity</button></section>`).join('')}</div>${state.leads.some(l=>l.stage==='Converted')?`<div class="panel panel-pad mt24"><h3>Converted relationships</h3><p class="sub">${state.leads.filter(l=>l.stage==='Converted').map(l=>esc(l.name)).join(' · ')}</p></div>`:''}${note('Client conversion creates a draft engagement only. Acceptance, effective terms, scope and access must remain distinct before professional work begins.','').replace('class="banner ','class="banner mt24 ')}${footer('LC-01–07')}`;}
function engagements(){const e=E();return head('Engagements','One legal scope, one reporting period, one accountable team.',btn('New engagement','new-eng','primary','','plus'))+context()+`<div class="panel panel-pad mb16"><div class="between"><div><span class="eyebrow">SELECTED ENGAGEMENT · ${e.id}</span><h2 class="mt8">${esc(C().name)}</h2><p class="sub">${esc(e.service)} · ${esc(e.period)} · ${esc(e.mode)}</p></div>${badge(stage(e))}</div>${lifeBar(e)}<div class="info-grid"><div><label>Engagement manager</label><span>${esc(e.manager)}</span></div><div><label>Professional signatory</label><span>${esc(e.partner)}</span></div><div><label>Management signatory</label><span>${esc(C().contact)}</span></div><div><label>Effective terms</label>${badge(e.terms?'Recorded':'Pending')}</div><div><label>Acceptance</label>${badge(e.acceptance?'Accepted':'Pending')}</div><div><label>Quality review</label><span>${e.eqrRequired?'Required for this demo profile':'Not required by this demo profile'}</span></div></div><div class="row mt24 wrap">${linkBtn('Accounting workspace','accounting')}${linkBtn('Audit workpapers','audit')}${linkBtn('Release gates','delivery')}${btn('View service scope','service-for-eng','sm')}</div></div>${panel('All engagements','Gate percentages describe this prototype state, not project implementation.',`<div class="tablewrap"><table><thead><tr><th>Client</th><th>Service</th><th>Stage</th><th>Demo gates</th><th>Target</th><th>Team</th><th></th></tr></thead><tbody>${engagementRows(state.engagements)}</tbody></table></div>`)}${footer('LC-09 · G02–03')}`;}
function lifeBar(e){const steps=['Acceptance','Planning','Production','Review','Release','Archive'];const ix=e.archive?5:e.releases.length?4:!allNotesClear(e)?3:!e.sourceAccepted?2:!e.planning?1:3;return `<div class="lifecyclebar">${steps.map((s,i)=>`<div class="life-step ${i<ix?'done':i===ix?'current':''}"><em>${i<ix?icon('check'):i+1}</em>${s}</div>`).join('')}</div>`;}
const assessmentItems=[['Identity & authority','Legal name, registration, addresses and authorized contacts','Q01–Q10'],['Financial & operational profile','Financial metrics, volumes, currencies and significant balances','Q11–Q19'],['Books, systems & evidence','Accounting mode, available records, framework and data permissions','Q20–Q29'],['Compliance & engagement suitability','Obligations, predecessor, management responsibility and firm capability','Q30–Q40']];
function onboarding(){const e=E(),q=e.questionnaire;return head('Acceptance is a decision, not a checkbox.','A guided preview of intake, supporting evidence and professional clearance.',btn('Read the exact questionnaire','source','', 'data-section="7"','book'))+context()+tabs([['assessment','Assessment'],['questions','Question bank'],['clearances','Clearances & terms']],'onboardTab')+note('This screen demonstrates the intake route. Completing demo declarations is not a KYC verification, screening result or professional acceptance.')+(ui.onboardTab==='assessment'?`<div class="grid-main"><div class="stack">${assessmentItems.map(([title,sub,ids],i)=>panel(title,sub,`<div class="panel-pad" style="padding-top:0"><div class="between"><span class="caption">${ids} · source requirements</span>${badge(q.answers[i]?'Demo information confirmed':'Awaiting information',q.answers[i]?'green':'amber')}</div><label class="checkbox mt16"><input type="checkbox" data-change="assessment-item" data-id="${i}" ${q.answers[i]?'checked':''}>I have reviewed the synthetic information and recorded the required demo evidence.</label><div class="mt12">${btn('Read source questions','source','ghost sm','data-section="7"')}</div></div>`)).join('')}</div><div class="stack"><div class="panel panel-pad"><span class="eyebrow">ASSESSMENT SUMMARY</span><h2 class="mt12">${Object.values(q.answers).filter(Boolean).length} of 4 sections</h2><div class="progress mt12" style="width:100%"><i style="width:${Object.values(q.answers).filter(Boolean).length*25}%"></i></div><p class="sub mt16">Scores and forms may route work. Only an authorized partner can record acceptance.</p><div class="divider"></div>${badge(q.status)}<div class="stack mt16">${btn('Submit demo assessment','assessment-submit','primary')}${btn('Record partner acceptance','assessment-accept','')}</div><p class="role-note">Use the Engagement partner role for the final decision. This is a simulation, not identity verification.</p></div><div class="panel panel-pad"><h3>Always distinguish</h3><p class="sub mt12">Information received → verified evidence → specialist clearance → partner decision → engagement authorization.</p></div></div></div>`:ui.onboardTab==='questions'?`<div class="panel panel-pad"><h2>Source intake and annual-validation questions</h2><p class="sub">Read-only source text. Q01–Q40 and Y01–Y30 are preserved in the document reference.</p>${sourceBlocks(PRD.sections.find(s=>s.id===7).blocks)}</div>`:`<div class="grid2">${panel('Required clearances','Each professional decision remains separate.',`<div class="panel-pad" style="padding-top:0"><div class="controlbox"><span class="statusicon">${icon('check')}</span><div><h4>Independence / service permissibility</h4><p>Synthetic scenario cleared; no real assessment performed.</p></div></div><div class="controlbox mt12"><span class="statusicon">${icon('check')}</span><div><h4>Capacity & competence</h4><p>Illustrative team assignment recorded.</p></div></div><div class="controlbox mt12"><span class="statusicon warn">${icon('info')}</span><div><h4>External screening</h4><p>Not connected. No sanctions or identity check is performed.</p></div></div></div>`)}${panel('Engagement terms','Commercial acceptance is not activation.',`<div class="panel-pad" style="padding-top:0">${badge(e.terms?'Effective terms recorded':'Terms pending')}<p class="sub mt16">Signed scope, entity, period, responsibilities, fees, data terms and signatory authority are required in production.</p><div class="mt20">${btn('Record demo terms','record-terms','soft')}</div></div>`)}</div>`)+footer('LC-04–07 · Q01–40');}
function documents(){const e=E(),items=e.pbc.filter(p=>ui.docFilter==='All'||p.status===ui.docFilter);return head('Evidence, with a clear chain of custody.','Every request has an owner, a period and a separate adequacy decision.',btn('New PBC request','new-pbc','primary','','plus'))+context()+`<div class="metric-grid">${metric('Requested',e.pbc.length,'Client evidence requests','folder')}${metric('Awaiting client',e.pbc.filter(p=>['Requested','Clarification required'].includes(p.status)).length,'Files or clarification outstanding','clock','amber')}${metric('Ready for review',e.pbc.filter(p=>p.status==='Received').length,'Received does not mean accepted','eye','purple')}${metric('Accepted',e.pbc.filter(p=>p.status==='Accepted').length,'Adequate for the stated request','checkcircle','blue')}</div><div class="toolbar"><select class="select" id="doc-filter" aria-label="Filter PBC requests">${['All','Requested','Received','Accepted','Clarification required'].map(s=>`<option ${ui.docFilter===s?'selected':''}>${s}</option>`).join('')}</select><span class="caption">Provider status: SharePoint is not connected</span></div>${panel('PBC request register','Sample files are visual references. Real uploads stay local and retain metadata only.',`<div class="tablewrap"><table><thead><tr><th>Request / document</th><th>Client owner</th><th>Due date</th><th>Status</th><th>Version</th><th class="right">Actions</th></tr></thead><tbody>${items.map(p=>`<tr><td><div class="row"><div class="document-icon ${p.file?.endsWith('.pdf')?'pdf':''}">${p.file?.endsWith('.pdf')?'PDF':'DOC'}</div><div><button class="tablelink" data-action="pbc-detail" data-id="${p.id}"><b>${esc(p.title)}</b></button><div class="cell-sub">${p.id} · ${esc(p.file||'No file received')}</div></div></div></td><td><span class="small">${esc(p.owner)}</span></td><td><span class="small">${shortDate(p.due)}</span></td><td>${badge(p.status)}</td><td class="mono">${p.version?'v'+p.version:'—'}</td><td class="right">${btn(p.file?'View request':'Upload','pbc-detail','sm',`data-id="${p.id}"`,p.file?'eye':'upload')}</td></tr>`).join('')}</tbody></table></div>`)}<div class="grid2 mt24"><div class="panel panel-pad"><h3>Receipt → review → accepted evidence</h3><div class="service-track mt16"><span>Requested</span>${icon('arrow')}<span>Received</span>${icon('arrow')}<span>Technical review</span>${icon('arrow')}<span>Accepted</span></div><p class="sub mt16">Replacement files retain their prior metadata and return to review. Internal review notes never become client-visible just because a query is shared.</p></div><div class="panel panel-pad"><div class="between"><h3>Document integration</h3>${badge('Not connected','gray')}</div><p class="sub mt12">The production architecture can resolve a logical document to an approved provider. This prototype does not upload to SharePoint, launch Office, or apply retention policies.</p>${btn('Read document requirements','source','ghost sm mt12','data-section="9"')}</div></div>${footer('LC-11–12 · API-07')}`;}
function accounting(){const e=E();return head('Accounting, from source to statement.','Preserve the original. Explain the adjustments. Review the exact reporting version.',`${btn('Export TB CSV','export-tb','','','download')}${btn('Import demo CSV','import-tb','primary','','upload')}`)+context()+tabs([['tb','Trial balance'],['mapping','Account mapping'],['adjustments','Adjustments'],['reconciliations','Reconciliations'],['statements','Financial statements']],'accountTab')+(e.builtGeneration!==e.generation?note(`<b>Package v${e.packageRevision} is stale.</b> Inputs changed to generation ${e.generation}. Rebuild, then obtain fresh approvals. Historical sign-offs remain attached to their original version.`,'amber',`<span class="banner-action">${btn('Rebuild package','build-package','sm soft')}</span>`):'')+({tb:tbView,mapping:mappingView,adjustments:adjustmentsView,reconciliations:reconciliationView,statements:statementsView}[ui.accountTab]||tbView)()+footer('LC-13–19 · GOV-01–03');}
function tbView(){const e=E(),t=totals(),raw=e.rows.reduce((s,r)=>s+r.balance,0),debits=e.rows.filter(r=>r.balance>0).reduce((s,r)=>s+r.balance,0);const rs=t.rows.map(r=>{const rawrow=e.rows.find(x=>x.code===r.code);const rawBal=rawrow?.balance||0;return `<tr><td class="mono">${esc(r.code)}</td><td><b>${esc(r.name)}</b><div class="cell-sub">${esc(r.type)} · ${e.id}</div></td><td class="right num">${moneyView(rawBal)}</td><td class="right num ${r.balance-rawBal?'teal':''}">${r.balance-rawBal?moneyView(r.balance-rawBal):'—'}</td><td class="right num bold">${moneyView(r.balance)}</td><td>${badge(e.mappingApproved?'Mapped':'Review required',e.mappingApproved?'green':'amber')}</td></tr>`;}).join('');return `<div class="grid3 mb16">${metric('Source debits',cash(debits),`Source version ${e.sourceVersion} · debit-positive convention`,'file')}${metric('Trial balance residual',cash(raw),raw===0?'Debits and credits agree':'Source requires correction','checkcircle',raw===0?'':'amber')}${metric('Adjusted profit',cash(t.profit),'Reporting adjustments applied once','trend','purple')}</div>${panel('Source and adjusted trial balance','QAR · Debit balances positive / credit balances in parentheses',`<div class="tablewrap"><table><thead><tr><th>Account</th><th>Description</th><th class="right">Source</th><th class="right">Adjustments</th><th class="right">Adjusted</th><th>Mapping</th></tr></thead><tbody>${rs}<tr class="table-summary"><td colspan="2">Signed-balance control</td><td class="right">${moneyView(raw)}</td><td class="right">${moneyView(t.balance-raw)}</td><td class="right">${moneyView(t.balance)}</td><td>${badge(t.balance===0?'Balanced':'Unbalanced',t.balance===0?'green':'red')}</td></tr></tbody></table></div><div class="panel-foot"><span>Received source → approved mapping → adjusted snapshot → report</span><span class="mono">TB-v${e.sourceVersion} / generation ${e.generation}</span></div>`,btn('Source fixture','source','ghost sm','data-section="25"'))}<div class="grid2 mt20"><div class="panel panel-pad"><h3>Try a controlled source replacement</h3><p class="sub mt8">Create a replacement TB already containing the depreciation entry. The reporting layer must not apply it a second time.</p><div class="mt16">${btn('Replace TB with posted adjustment','replace-tb','soft','','refresh')}</div></div><div class="panel panel-pad"><h3>Demonstrate approval invalidation</h3><p class="sub mt8">Add a synthetic QAR 1,000 credit sale: receivables and revenue change. Existing package approvals become stale.</p><div class="mt16">${btn('Simulate source change','source-change','','','layers')}</div></div></div>${note('The initial 8-account fixture and QAR 500 adjustment come from PRD §25. Other clients and supplemental schedules are illustrative. This is not a production ledger.','').replace('class="banner ','class="banner mt20 ')}`;}
function mappingView(){const e=E();return note('Mappings classify source accounts. Changing an account classification creates a new input generation and requires a fresh reviewer decision.')+panel('Account-to-statement mapping','Select the destination classification, then switch to Senior reviewer to approve.',`<div class="tablewrap"><table><thead><tr><th>Source code</th><th>Source account</th><th>Statement classification</th><th>Review</th></tr></thead><tbody>${e.rows.map(r=>`<tr><td class="mono">${esc(r.code)}</td><td>${esc(r.name)}</td><td><select class="select" data-change="mapping" data-code="${esc(r.code)}" aria-label="Classification for ${esc(r.name)}">${['asset','liability','equity','revenue','expense'].map(t=>`<option value="${t}" ${r.type===t?'selected':''}>${{asset:'Assets → Financial position',liability:'Liabilities → Financial position',equity:'Equity → Equity statement',revenue:'Revenue → Profit or loss',expense:'Expenses → Profit or loss'}[t]}</option>`).join('')}</select></td><td>${badge(e.mappingApproved?'Approved':'Review required')}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot"><span>Prototype supports one classification per account; split allocations are a production requirement.</span>${btn('Approve mapping','approve-mapping','primary sm')}</div>`) + `<div class="panel panel-pad mt20"><h3>Reporting traceability</h3><div class="lineage mt16"><span>Source account</span>${icon('arrow')}<span>Entity account</span>${icon('arrow')}<span>Approved mapping</span>${icon('arrow')}<span>Statement line</span>${icon('arrow')}<span>Supporting note</span></div></div>`;}
function adjustmentsView(){const e=E();return `<div class="grid-main"><div class="stack">${panel('AJ-001 · Depreciation adjustment','Based on the worked example in STE-PRD-001 §25.3.',`<div class="panel-pad" style="padding-top:0"><div class="between">${badge(e.journalState)}${badge(e.sourceReflection?'Reflected in source':'Reporting layer',e.sourceReflection?'blue':'purple')}</div><div class="tablewrap mt20"><table><thead><tr><th>Account</th><th class="right">Debit</th><th class="right">Credit</th></tr></thead><tbody><tr><td>Depreciation expense</td><td class="right">${fmt(e.adjustment)}</td><td class="right">—</td></tr><tr><td>Accumulated depreciation</td><td class="right">—</td><td class="right">${fmt(e.adjustment)}</td></tr></tbody></table></div><div class="info-grid mt20"><div><label>Prepared by</label><span>Adam Khan</span></div><div><label>Technical review</label><span>Sara Malik · sample record</span></div><div><label>Management</label><span>${e.journalState==='Applied'?'Demo authorization recorded':'Authorization pending'}</span></div></div><div class="divider"></div><p class="small muted">${e.sourceReflection?'The replacement trial balance already includes this entry. Additional reporting-layer effect is QAR 0.00.':'The approved reporting adjustment is included once. The client’s external ledger is not changed by this application.'}</p><div class="row mt16 wrap">${btn('Revise proposed amount','revise-adjustment','','','file')}${e.journalState!=='Applied'?btn('Management authorize & apply demo','apply-adjustment','primary'):''}</div></div>`)}${panel('Correction lineage','Every change keeps a source and decision trail.',`<div class="panel-pad" style="padding-top:0"><div class="lineage"><span>WP-C1</span>${icon('arrow')}<span>AJ-001</span>${icon('arrow')}<span>Management decision</span>${icon('arrow')}<span>TB-v${e.sourceVersion}</span>${icon('arrow')}<span>Package-v${e.packageRevision}</span></div></div>`)}</div><div class="stack"><div class="panel panel-pad"><h3>Four different outcomes</h3><div class="status-line mt16">${icon('check')}Technical treatment reviewed</div><div class="status-line">${icon('check')}Management authorization</div><div class="status-line">${icon('layers')}Included in reporting</div><div class="status-line">${icon('globe')}Externally posted: separate evidence</div><p class="sub mt16">A downloaded journal file is not evidence of external posting. A rejected entry remains in the differences register.</p></div>${note('All journal actions are local simulations. No client or firm ledger receives a posting.','amber')}</div></div>`;}
function reconciliationView(){const e=E();return panel('Source-bound reconciliations','Opening balances, supporting schedules and explained differences.',`<div class="tablewrap"><table><thead><tr><th>Area</th><th>Reference</th><th>Supporting basis</th><th>Status</th><th></th></tr></thead><tbody>${e.reconciliations.map((r,i)=>`<tr><td><b>${r.name}</b></td><td class="mono">${r.ref}</td><td class="small muted">${r.evidence}</td><td>${badge(r.status)}</td><td>${btn('Open schedule','reconciliation','sm',`data-id="${i}"`)}</td></tr>`).join('')}</tbody></table></div>`)+`<div class="panel panel-pad mt20"><h3>Unexplained differences cannot be hidden</h3><p class="sub mt8">The production workflow classifies timing, error, omission, estimates and disputed items. This prototype displays sample reconciliation outcomes; it does not perform bank matching.</p><div class="mt12">${btn('Read detailed reconciliation requirements','source','ghost sm','data-section="10"')}</div></div>`;}
function statementPaper(e=E(),release=null){const t=release?.totals||totals(e),rev=release?.revision||e.packageRevision,c=C(e.client);return `<article class="paper"><div class="watermark">${release?'DEMO ISSUED ARTIFACT — NOT AN AUDITOR’S REPORT':'ILLUSTRATIVE DRAFT — NOT FOR PROFESSIONAL USE'}</div><div class="letterhead"><div><h2>${esc(c.name)}</h2><p>Illustrative financial statements · FY ${e.year}</p></div><div class="right"><strong>QAR</strong><div class="caption">Package v${rev}</div><div class="caption">STE-PRD-001 demonstration</div></div></div><h3>Statement of financial position</h3><table><thead><tr><th>Line item</th><th class="right">Amount</th></tr></thead><tbody>${t.rows.filter(r=>r.type==='asset').map(r=>`<tr><td>${esc(r.name)}</td><td class="right num">${moneyView(r.balance)}</td></tr>`).join('')}<tr class="statement-total"><td>Total assets</td><td class="right">${fmt(t.assets)}</td></tr>${t.rows.filter(r=>r.type==='liability').map(r=>`<tr><td>${esc(r.name)}</td><td class="right">${moneyView(-r.balance)}</td></tr>`).join('')}<tr><td>Total liabilities</td><td class="right">${fmt(t.liabilities)}</td></tr><tr><td>Opening equity</td><td class="right">${fmt(t.openingEquity)}</td></tr><tr><td>Current-period profit / (loss)</td><td class="right">${moneyView(t.profit)}</td></tr><tr class="statement-total"><td>Total liabilities and equity</td><td class="right">${fmt(t.liabilities+t.openingEquity+t.profit)}</td></tr></tbody></table><h3>Statement of profit or loss</h3><table><tbody>${t.rows.filter(r=>['revenue','expense'].includes(r.type)).map(r=>`<tr><td>${esc(r.name)}</td><td class="right">${moneyView(r.type==='revenue'?-r.balance:r.balance)}</td></tr>`).join('')}<tr class="statement-total"><td>Profit / (loss) for the period</td><td class="right">${moneyView(t.profit)}</td></tr></tbody></table><h3>Equity movement</h3><p>Opening equity ${cash(t.openingEquity)} + current result ${cash(t.profit)} = closing equity ${cash(t.openingEquity+t.profit)}. This simplified illustration assumes no distributions or other comprehensive income.</p><h3>Cash-flow and disclosure support</h3>${e.supplements?`<p><b>Illustrative supporting schedule, not derived from closing TB alone.</b> The original example assumes opening cash QAR 8,000 and a QAR 1,000 increase in receivables: operating cash QAR 2,000, no investing or financing movements, closing cash QAR 10,000. These demo assumptions apply only to the original Example Trading fixture; source changes require new supporting schedules.</p><p>Disclosure checklist: accounting basis, asset policy, related parties, going concern and subsequent events require explicit applicability and review. This preview is not a complete framework-compliant statement set.</p>`:`<p><strong>Supporting schedules require review.</strong> Opening balances, cash movements, noncash changes and disclosure information must be supplied. A closing trial balance is insufficient.</p>`}<div class="divider"></div><div class="caption">Source: ${e.id} · TB-v${e.sourceVersion} · input generation ${release?.generation||e.generation}<br>No real signature, audit opinion, management attestation or filing is created by this prototype.</div></article>`;}
function statementsView(){const e=E(),t=totals();return `<div class="toolbar">${btn('Rebuild current package','build-package','primary','','refresh')}${btn('Export preview HTML','export-report','','','download')}${btn('Print preview','print-report','','','file')}${linkBtn('Approval desk','reviews')}</div><div class="grid3 mb16">${metric('Total assets',cash(t.assets),'Statement of financial position','chart')}${metric('Closing equity',cash(t.openingEquity+t.profit),'Opening equity + current-period result','layers','purple')}${metric('Statement equation',t.assets===t.liabilities+t.openingEquity+t.profit?'Balanced':'Review required','Assets = liabilities + equity','checkcircle','blue')}</div>${!e.supplements?note('After a source change, the illustrative cash-flow/disclosure support must be reconfirmed. This demo confirmation does not create real evidence.','amber',`<span class="banner-action">${btn('Review demo supplements','supplements','sm')}</span>`):''}${statementPaper()}<div class="row mt20 wrap">${btn('Review demo supplements','supplements','soft')}${btn('Read statement requirements','source','ghost','data-section="10"')}</div>`;}
function audit(){const e=E(), prog=auditWorkpaperProgress(e);return head('Evidence that supports a conclusion.','Plan, test and review without losing the source version.',btn('Planning & materiality','planning','primary','','target'))+context()+tabs([['workpapers','Working papers'],['risks','Risks & assertions'],['sampling','Population & sampling'],['memoranda','Memoranda']],'auditTab')+(ui.auditTab==='workpapers'?`<div class="metric-grid">${metric('Audit workpapers',prog.total,'Across all planned audit areas','checkboard')}${metric('Applicable areas',prog.applicable,'Subject to substantive testing','target')}${metric('Cleared areas',prog.cleared,'Current independent clearance','checkcircle','blue')}${metric('Audit completion',prog.percent+'%','Cleared applicable audit areas','shield','green')}</div><div class="wp-progress-card"><div class="wp-progress-info"><h3>Audit Execution & Clearance Progress</h3><p class="sub" style="color:#d4e9e2;margin-top:4px">Progress reflects independently cleared working papers for the current source version (TB-v${e.sourceVersion}) and input generation ${e.generation}.</p></div><div style="text-align:right"><div class="wp-progress-stat"><span style="font-size:24px;font-weight:700">${prog.percent}%</span><div style="font-size:11px;color:#a2cfba">${prog.cleared} of ${prog.applicable} cleared</div></div><div class="wp-progress-bar mt8"><i style="width:${prog.percent}%"></i></div></div></div>${panel('Audit execution & clearance index','Execute procedures, upload working papers, attach evidence, and obtain independent clearance.',`<div class="tablewrap"><table><thead><tr><th>Reference / area</th><th>Assertion focus</th><th>Working paper</th><th>Evidence</th><th>Notes</th><th>Status</th><th>Reviewer</th><th></th></tr></thead><tbody>${e.workpapers.map(w=>{const curClr=isCurrentWorkpaperClearance(w,e);const openNotes=e.reviews.filter(r=>r.wp===w.id&&r.status!=='Cleared').length;return `<tr><td><b>${esc(w.title)}</b><div class="cell-sub">${w.id} · Rev v${w.version}</div></td><td class="small">${esc(w.assertion)}</td><td>${w.workingPaper?`<span class="attachment-chip" title="${esc(w.workingPaper.file)}">${icon('file')}${esc(w.workingPaper.file.length>20?w.workingPaper.file.slice(0,18)+'…':w.workingPaper.file)}</span>`:'<span class="caption muted">No workbook</span>'}</td><td>${w.supportingEvidence.length?`<span class="tag gray">${w.supportingEvidence.length} item${w.supportingEvidence.length===1?'':'s'}</span>`:'<span class="caption muted">—</span>'}</td><td>${openNotes?`<span class="tag red">${openNotes} open</span>`:'<span class="caption muted">0</span>'}</td><td>${w.applicable===false?badge('Not applicable','gray'):curClr?badge('Cleared','green'):w.status==='Cleared'?badge('Clearance stale','red'):badge(w.status)}</td><td><div class="row gap8">${avatar('SM','purple','sm')}<span class="small">${esc(w.reviewer||'Sara Malik')}</span></div></td><td>${btn('Workspace','workpaper','sm',`data-id="${w.id}"`,'arrow')}</td></tr>`;}).join('')}</tbody></table></div>`)}<div class="panel panel-pad mt20"><h3>Evidence chain</h3><div class="lineage mt16">${['Guidance','Approved Template','Work Performed','Working Paper Upload','Supporting Evidence','Review Points','Preparer Response','Reviewer Clearance'].map((t,i)=>`<span>${t}</span>${i<7?icon('arrow'):''}`).join('')}</div></div>`:ui.auditTab==='risks'?`<div class="grid2">${e.workpapers.map(w=>`<section class="panel panel-pad"><div class="between"><span class="eyebrow">${w.id}</span>${badge('Engagement-specific','purple')}</div><h3 class="mt12">${esc(w.risk)}</h3><p class="sub mt8">${esc(w.assertion)}</p><p class="small mt16">${esc(w.objective)}</p><div class="mt16">${btn('Open workspace','workpaper','soft sm',`data-id="${w.id}"`,'link')}</div></section>`).join('')}</div>`:ui.auditTab==='sampling'?samplingView():memorandaView())+footer('AUD-01–05 · LC-10');}
function samplingView(){return note('This is a sampling-workflow illustration, not a statistical sampling engine. No confidence level or assurance is implied by selecting demonstration rows.','amber')+`<div class="grid-main"><div class="panel panel-pad"><h2>Receivables population</h2><p class="sub">A miniature synthetic population for exploring the evidence workflow.</p><div class="tablewrap mt20"><table><thead><tr><th>Source ID</th><th>Counterparty</th><th class="right">QAR</th><th>Selection</th></tr></thead><tbody>${[['AR-01','Demo Customer A',250000],['AR-02','Demo Customer B',175000],['AR-03','Demo Customer C',75000]].map(([id,name,value],i)=>`<tr><td class="mono">${id}</td><td>${name}</td><td class="right">${fmt(value)}</td><td>${badge(i===0?'Specific item':'Unselected',i===0?'purple':'gray')}</td></tr>`).join('')}</tbody></table></div><p class="sub mt20">This example population totals QAR 5,000 for the original Example Trading fixture. Reconcile the actual source and define the testing objective before real selections.</p></div><div class="panel panel-pad"><h3>Selection plan</h3><div class="info-grid mt20" style="grid-template-columns:1fr"><div><label>Method</label><span>Specific-item selection · demonstration</span></div><div><label>Objective</label><span>Inspect support for one high-value receivable</span></div><div><label>Evaluation</label><span>No projection to the untested remainder</span></div></div>${btn('Record illustrative test','sample-result','primary mt24')}</div></div>`;}
function memorandaView(){return `<div class="grid2">${[['Strategy memorandum','Scope, entity understanding, significant areas, materiality, procedures, team and timing.','planning'],['Summary memorandum','Work performed, findings, estimates, differences, going concern, subsequent events and reporting conclusion.','summary-memo'],['Audit announcement','Approved scope, intended dates, support required and contact responsibilities.','announcement'],['Report / service conclusion','Version-bound report, supporting conclusion and the authorized final package.','report-memo']].map(([title,sub,action])=>`<div class="panel panel-pad"><span class="metric-icon">${icon('file')}</span><h3 class="mt16">${title}</h3><p class="sub mt8">${sub}</p><div class="mt16">${btn('Open illustrative document',action,'soft sm')}</div></div>`).join('')}</div>`;}
function reviews(){const e=E();const r=e.reviews.find(r=>r.id===ui.selectedReview)||e.reviews[0];return head('Review the work. Preserve the decision.','Responses, independent clearance and exact-version sign-off remain separate.',btn('Demonstrate a source change','source-change','','','refresh'))+context()+tabs([['notes','Review points'],['approvals','Package approvals'],['history','Decision history']],'reviewTab')+(ui.reviewTab==='notes'?(r?`<div class="review-split"><div class="panel"><div class="panel-head"><h2>Review queue</h2><span class="tag gray">${e.reviews.filter(n=>n.status!=='Cleared').length} open</span></div>${e.reviews.map(n=>`<button class="review-selector ${n.id===r.id?'active':''}" data-action="select-review" data-id="${n.id}"><div class="between"><span class="mono">${n.id}</span>${badge(n.severity,n.severity==='High'?'red':'amber')}</div><h3>${esc(n.title)}</h3><p>${n.wp} · due ${shortDate(n.due)}</p><div class="mt12">${badge(n.status)}</div></button>`).join('')}<div class="panel-pad">${btn('Add review point','add-note','soft sm','','plus')}</div></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">${r.id} · ${r.wp}</span><h2 class="mt8">${esc(r.title)}</h2></div>${badge(r.status)}</div><div class="panel-pad" style="padding-top:0"><div class="row"><span class="caption">Raised by ${esc(r.raisedBy)}</span><span class="caption">Assigned to ${esc(r.assigned)}</span></div><div class="comment"><div class="row gap8">${avatar('SM','purple','sm')}<b class="small">Reviewer’s request</b></div><p>${esc(r.body)}</p></div><div class="lineage"><span>${r.wp}-v${r.version}</span>${icon('link')}<span>TB-v${e.sourceVersion}</span>${icon('link')}<span>Package-v${e.packageRevision}</span></div>${r.response?`<div class="comment" style="background:#f1f8f4;border-color:#dbe9e0"><div class="row gap8">${avatar('AK','','sm')}<b class="small">Response from ${esc(r.respondedBy||'Adam Khan')}</b></div><p>${esc(r.response)}</p><p class="caption">A response is not clearance. The reviewer must assess it.</p></div>`:''}<div class="field mt24"><label for="review-response">Response and supporting evidence explanation</label><textarea class="input" id="review-response" placeholder="Describe the correction, evidence supplied, and revised conclusion…">${esc(r.status==='Open'?'':r.response)}</textarea></div><div class="row mt16 wrap">${btn('Submit response & revision','respond-note','primary',`data-id="${r.id}"`,'send')}${btn('Clear as reviewer','clear-note','',`data-id="${r.id}"`,'check')}${r.status==='Cleared'?btn('Reopen','reopen-note','danger',`data-id="${r.id}"`):''}</div><div class="role-note">Simulated role: <b>${actor().label}</b>. Use Preparer to respond and Senior reviewer to clear. Browser role switching is not real authentication.</div>${r.status==='Cleared'?note('This review point is cleared for the recorded workpaper revision. A later relevant change reopens review and invalidates dependent package approvals.'):''}</div></div></div>`:note('There are no review points in this selected engagement. Workpapers and package gates still require their own review.')):ui.reviewTab==='approvals'?approvalView():historyView())+footer('LC-20–23 · GOV-01–04');}
function approvalView(){const e=E();return note(`Approval decisions bind to package <b>v${e.packageRevision}</b> and input generation <b>${e.generation}</b>. This prototype simulates the decisions; it creates no real signatures.`)+(e.builtGeneration!==e.generation?note('Rebuild the package before signing off.','amber',`<span class="banner-action">${btn('Rebuild','build-package','sm')}</span>`):'')+`<div class="panel panel-pad mb16"><div class="between"><div><h3>Readiness before package approval</h3><p class="sub">Review notes and working papers must be cleared; supporting schedules must be available.</p></div>${btn('Preview exact draft','preview-report','soft sm','','eye')}</div><div class="row wrap mt16">${badge(allNotesClear()?'Review notes cleared':'Review notes open')}${badge(allWorkClear()?'Workpapers cleared':'Workpapers require review')}${badge(e.supplements?'Supplements available':'Supplements pending')}</div></div><div class="approvals">${[['manager','Manager review','Internal consistency and significant judgments.'],['client','Management approval','The client approves its accounts, not the audit opinion.'],['partner','Partner authorization','Professional conclusion and exact package release.'],['eqr','Quality review','Separate eligibility and completion where required.']].map(([key,title,desc])=>{const a=e.approvals[key],current=isCurrent(key);return `<section class="approval-card ${current?'approved':''}"><span class="statusicon ${current?'':'pending'}">${icon(current?'check':'user')}</span><h4>${title}</h4>${badge(key==='eqr'&&!e.eqrRequired?'Not required':current?'Current approval':a?'Stale approval':'Pending',key==='eqr'&&!e.eqrRequired?'gray':current?'green':a?'red':'amber')}<p>${desc}</p>${a?`<p>${esc(a.actor)}<br>v${a.packageRevision} · generation ${a.generation}</p>`:''}${btn('Record demo approval','package-approve','sm '+(current?'':'primary'),`data-key="${key}" ${key==='eqr'&&!e.eqrRequired?'disabled':''}`)}</section>`;}).join('')}</div><div class="panel panel-pad mt20"><div class="between"><div><h3>Next: prepare the release candidate</h3><p class="sub">Issue only the selected, current, fully approved package.</p></div>${linkBtn('Delivery & archive','delivery')}</div></div>`;}
function historyView(){const e=E();return panel('Decision and change history','Local demo events; not a tamper-proof or production audit log.',`<div class="panel-pad" style="padding-top:0">${e.events.length?e.events.map(ev=>`<div class="activity"><div class="activity-dot">${icon(ev.type)}</div><div><p>${esc(ev.text)}</p><small>${esc(ev.time)} · ${esc(ev.ref)}</small></div></div>`).join(''):'<div class="empty">No new demo decisions yet. Respond to a review point or record an approval.</div>'}</div>`);}
function delivery(){const e=E(),blockers=releaseBlockers();const gates=[['G01','Acceptance',e.acceptance],['G02','Activation / terms',e.terms],['G03','Planning',e.planning],['G04','Financial intake',e.sourceAccepted&&e.mappingApproved&&totals().balance===0],['G05','Production complete',allWorkClear()&&e.supplements&&e.builtGeneration===e.generation],['G06','Senior clearance',allNotesClear()],['G07','Manager completion',isCurrent('manager')],['G08','Management approval',isCurrent('client')],['G09','Professional release',isCurrent('partner')&&(!e.eqrRequired||isCurrent('eqr'))],['G10','Delivery recorded',e.releases.some(r=>r.delivered)],['G11','Archive assembled',!!e.archive],['G12','Renewal / offboarding',!!e.annual.nextId]];return head('Only the right version leaves the practice.','A frozen package, explicit authority and a traceable delivery record.',btn('Preview current package','preview-report','','','eye'))+context()+note('All issue, delivery, signing and archive actions below are simulations. No report is sent, legally signed, filed or protected in Microsoft Purview.','amber')+`<div class="grid-main"><div class="stack">${panel('Release readiness','Gates are evaluated from the current demo state.',`<div class="panel-pad" style="padding-top:0"><div class="gate-grid">${gates.map(([id,title,ok])=>`<div class="controlbox"><span class="statusicon ${ok?'':'pending'}">${icon(ok?'check':'clock')}</span><div><span class="eyebrow">${id}</span><h4>${title}</h4></div></div>`).join('')}</div></div>`)}${panel('Issued sample packages','Issued snapshots remain unchanged if you edit the working source.',`<div class="panel-pad" style="padding-top:0">${e.releases.length?e.releases.map((r,i)=>`<div class="borderbox ${i?'mt12':''}"><div class="between"><div><h3>${r.id} · package v${r.revision}</h3><p class="sub">${esc(r.issuedAt)} · ${esc(r.author)}</p></div>${badge(r.delivered?'Demo delivered':'Demo issued')}</div><div class="hash mt12">SHA-256: ${r.hash}</div><div class="row mt12 wrap">${btn('View preserved preview','released-preview','sm',`data-id="${r.id}"`,'eye')}${btn('Export manifest JSON','release-export','sm',`data-id="${r.id}"`,'download')}${!r.delivered?btn('Record demo delivery','demo-deliver','soft sm',`data-id="${r.id}"`):''}</div></div>`).join(''):'<div class="empty">No issued packages. Complete the required gates first.</div>'}</div>`)}</div><div class="stack"><div class="focus-card"><div class="focus-label">CURRENT CANDIDATE</div><h2 class="mt12">${blockers.length?blockers.length+' release blockers':'Ready for a demo release'}</h2><p>${blockers.length?'Required reviews and source dependencies must be current.':'The selected version has satisfied the simulated prerequisites.'}</p>${blockers.length?`<div class="stack gap8 small" style="color:#617869">${blockers.map(b=>`<div class="row gap8">${icon('clock')}<span>${esc(b)}</span></div>`).join('')}</div><div class="mt16">${btn('Go to approval desk','open-approvals','primary sm','','arrow')}</div>`:`<div class="stack">${btn('Prepare demo candidate','prepare-release','primary')}${e.candidate?btn('Issue demo package','issue-release','soft'):''}</div>`}</div>${e.candidate?`<div class="panel panel-pad"><h3>Frozen candidate</h3><p class="sub">Package v${e.candidate.revision} · generation ${e.candidate.generation}</p><div class="hash mt12">${e.candidate.hash}</div><p class="sub mt12">The hash identifies local manifest bytes. It is not a digital signature.</p></div>`:''}<div class="panel panel-pad"><h3>Archive & retention</h3><p class="sub mt12">${e.archive?'The demonstration manifest was assembled. Storage immutability and legal retention remain unimplemented.':'After demo delivery, a records custodian can assemble the local archive manifest.'}</p><div class="mt16">${btn('Assemble demo archive','archive','soft sm','','archive')}</div><div class="mt12">${badge(e.archive?'Simulation complete':'Not assembled',e.archive?'green':'gray')}</div><div class="divider"></div>${btn('Read offboarding requirements','source','ghost sm','data-section="13"')}</div></div></div>${footer('G01–12 · LC-24–26')}`;}
function portal(){const e=E(),c=C();return head('Client portal preview','A separate, simplified view of requests, responsibilities and released deliverables.',btn('Return to staff workspace','open-overview','','','left'))+context()+note('You are previewing the client experience. This browser demo has no real authentication or access isolation; all available records are synthetic.')+`<div class="portal-hero"><span class="eyebrow" style="color:#aad6bf">${esc(c.name)} · FY ${e.year}</span><h2 class="mt12">Good morning, ${esc(c.contact.split(' ')[0])}.</h2><p>Your engagement team has ${e.pbc.filter(p=>p.status!=='Accepted').length} open document requests. Everything you need is in one place.</p></div><div class="grid-main"><div class="stack">${panel('Your document requests','Supply the requested period and entity; your team reviews adequacy separately.',`<div class="panel-list">${e.pbc.map(p=>`<div class="list-item"><div class="row"><div class="document-icon">DOC</div><div><div class="list-item-title">${esc(p.title)}</div><div class="list-item-sub">Due ${shortDate(p.due)} · ${p.id}</div></div></div><div class="row gap8">${badge(p.status)}${btn(p.file?'View':'Upload','pbc-detail','sm',`data-id="${p.id}"`,p.file?'eye':'upload')}</div></div>`).join('')}</div>`)}${panel('Your deliverables','Only expressly published sample packages appear here.',`<div class="panel-pad" style="padding-top:0">${e.releases.filter(r=>r.delivered).length?e.releases.filter(r=>r.delivered).map(r=>`<div class="list-item"><div><b>${r.id}</b><p class="sub">FY ${e.year} · package v${r.revision} · demo only</p></div>${btn('View package','released-preview','sm',`data-id="${r.id}"`)}</div>`).join(''):'<div class="empty">Your final deliverables will appear after authorized release and delivery.</div>'}</div>`)}</div><div class="stack"><div class="panel panel-pad"><span class="eyebrow">MANAGEMENT REVIEW</span><h2 class="mt12">Financial statements v${e.packageRevision}</h2><p class="sub mt12">Review the exact draft. Management accepts responsibility for its accounts—not the auditor’s independent conclusion.</p><div class="stack mt20">${btn('Review draft statements','preview-report','soft','','eye')}${btn('Record management approval','portal-approve','primary')}</div><div class="mt16">${badge(isCurrent('client')?'Approval current':e.approvals.client?'Approval stale':'Awaiting management')}</div></div><div class="panel panel-pad"><h3>Your engagement team</h3><div class="row mt16">${avatar('LR','purple')}<div><b class="small">Layla Rahman</b><div class="caption">Engagement manager</div></div></div><p class="sub mt16">Demo contact only. Messages are recorded locally; no email is sent.</p><div class="mt16">${btn('Ask a question','client-query','sm','','message')}</div></div></div></div>${footer('LC-07 · LC-11–12 · LC-22')}`;}
function billing(){const list=state.invoices;return head('Practice billing, separate from client books.','Manage professional fees and time without changing client financial statements.',btn('Log demo time','log-time','primary','','plus'))+note('All invoices are sample firm records. Receipts are local demonstrations, not payment requests, transactions or payment-gateway confirmations.')+`<div class="metric-grid">${metric('Invoiced',cash(list.filter(i=>i.status!=='Draft').reduce((s,i)=>s+i.amount,0)),'Issued sample fee invoices','receipt')}${metric('Collected',cash(list.reduce((s,i)=>s+i.paid,0)),'Recorded demo receipts only','checkcircle','blue')}${metric('Outstanding',cash(list.filter(i=>i.status!=='Draft').reduce((s,i)=>s+i.amount-i.paid,0)),'Firm receivables, not client revenue','clock','amber')}${metric('Logged time',state.times.reduce((s,t)=>s+t.hours,0).toFixed(1)+' h','Illustrative practice time entries','brief','purple')}</div>${panel('Fee invoice register','Office ledger scope · client books remain unchanged',`<div class="tablewrap"><table><thead><tr><th>Invoice / client</th><th>Service milestone</th><th class="right">Amount</th><th class="right">Outstanding</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td><b>${i.id}</b><div class="cell-sub">${esc(C(i.client)?.name||'Client')}</div></td><td class="small">${esc(i.description)}</td><td class="right">${fmt(i.amount)}</td><td class="right">${fmt(i.amount-i.paid)}</td><td>${badge(i.status,i.status==='Paid'?'green':i.status==='Issued'?'blue':'amber')}</td><td>${btn('Open','invoice','sm',`data-id="${i.id}"`,'arrow')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Time entries','New demo entries are stored locally.',`<div class="tablewrap"><table><thead><tr><th>Person</th><th>Task</th><th>Engagement</th><th class="right">Hours</th></tr></thead><tbody>${state.times.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.task)}</td><td class="mono">${esc(t.eng)}</td><td class="right">${t.hours.toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`).replace('class="panel"','class="panel mt20"')}${footer('BIL-01–04')}`;}
const annualGroups=[['Y01–Y05','Legal identity & activities','Confirm legal name, registration, addresses, year-end and activities.'],['Y06–Y10','Ownership & relationships','Confirm owners, signatories, group structure, countries and related parties.'],['Y11–Y15','Financial profile','Confirm actual/forecast metrics, financing and going-concern facts.'],['Y16–Y20','Books, systems & records','Confirm framework, currency, interfaces, reconciliations, assets and payroll.'],['Y21–Y25','Obligations & findings','Confirm filing obligations, investigations, controls, findings and events.'],['Y26–Y30','Services, access & attestation','Confirm services, deadlines, responsibilities, access and authorized attestation.']];
function continuance(){const e=E();return head('A fresh year starts with fresh decisions.','Carry forward useful context—not last year’s approvals or conclusions.',btn('Read annual questionnaire','source','','data-section="7"','book'))+context()+`<div class="grid-main"><div class="stack">${panel('Prior period → next period','Grouped exactly as Y01–Y30 in the requirements; confirmations are illustrative.',`<div class="panel-pad" style="padding-top:0">${annualGroups.map(([id,title,desc],i)=>`<div class="question-row"><div><span class="eyebrow">${id}</span><h3 class="mt8">${title}</h3><small>${desc}</small></div><label class="checkbox"><input type="checkbox" data-change="annual" data-id="${i}" ${e.annual.confirmed.includes(i)?'checked':''}><span class="small">Reviewed</span></label></div>`).join('')}</div>`)}${panel('Example change report','A demonstration of field-level comparison, not an actual client declaration.',`<div class="tablewrap"><table><thead><tr><th>Field</th><th>Prior period</th><th>New period</th><th>Action</th></tr></thead><tbody><tr><td>Financial year-end</td><td>31 December</td><td>31 December</td><td>${badge('Reconfirm','gray')}</td></tr><tr class="changed"><td>Ownership</td><td>Existing owner</td><td>New shareholder declared</td><td>${badge('Evidence required','amber')}</td></tr><tr class="changed"><td>Accounting system</td><td>Prior source system</td><td>New export layout</td><td>${badge('Import review','purple')}</td></tr></tbody></table></div>`)}</div><div class="stack"><div class="panel panel-pad"><span class="eyebrow">CONTINUANCE DECISION</span><h2 class="mt12">${e.year} → ${e.year+1}</h2><p class="sub mt12">${e.annual.confirmed.length} of 6 grouped sections reviewed. The partner’s decision remains independent of a “no change” answer.</p><div class="mt16">${badge(e.annual.decision||'Decision pending')}</div><div class="stack mt20">${btn('Record demo continuance','continue-client','primary')}${btn('Create next-year draft','roll-forward','soft')}</div><p class="role-note">A draft shell contains only reference structure. It does not copy current-year balances, samples, evidence or approvals.</p>${e.annual.nextId?`<p class="sub mt12">New draft: ${esc(e.annual.nextId)}</p>`:''}</div><div class="panel panel-pad"><h3>Exit paths remain controlled</h3><p class="sub mt12">Suspension, termination, handover and disposition have separate responsibilities. Termination does not authorize evidence deletion.</p><div class="mt12">${btn('View offboarding path','offboarding','sm','','archive')}</div></div></div></div>${footer('LC-08 · LC-25–26')}`;}
function services(){const services=PRD.services.filter((s,i)=>i<12&&s.title.toLowerCase().includes(ui.serviceFilter.toLowerCase()));const icons=['shield','target','chart','book','search','trend','checkboard','brief','layers','folder','settings','users'];return head('One practice. Different professional services.','Service-specific inputs, procedures, deliverables and approval routes.',btn('Read catalogue requirements','source','','data-section="17"','book'))+note('These cards visualize the service requirements, not delivered calculation engines or approved methodologies. Each service needs its own production workflow and acceptance tests.')+`<div class="toolbar"><div class="input-search">${icon('search')}<input class="input" id="service-filter" value="${esc(ui.serviceFilter)}" placeholder="Search service catalogue" aria-label="Filter services"></div><span class="tag gray">12 source service families</span></div><div class="grid3">${services.map(s=>{const i=PRD.services.indexOf(s);const title=s.title.replace(/^17\.\d+\s*/,''),out=s.blocks.find(b=>b.text?.startsWith('Output and approval'))?.text.replace('Output and approval: ','')||'';return `<section class="service-card"><div class="between" style="width:100%"><div class="icon-tile">${icon(icons[i])}</div><span class="eyebrow">17.${i+1}</span></div><h3>${esc(title)}</h3><p>${esc(out.length>150?out.slice(0,147)+'…':out)}</p>${btn('Explore required workflow','service-detail','ghost sm',`data-id="${i}"`,'arrow')}</section>`;}).join('')}</div><div class="panel panel-pad mt24"><h3>Additional practice templates</h3><div class="row wrap mt16">${['Recurring bookkeeping','Annual accounts / compilation','Review engagements','Agreed-upon procedures','Tax compliance','Payroll administration'].map(s=>`<span class="tag gray">${s}</span>`).join('')}</div><div class="mt12">${btn('Explore additional service requirements','service-detail','ghost sm','data-id="12"')}</div></div>${footer('§17 · AT-11')}`;}
function sourceBlocks(blocks){return `<div class="reference-block">${blocks.map(b=>b.kind==='table'?`<div class="tablewrap"><table><tbody>${b.rows.map(row=>`<tr>${row.map(c=>`<td>${esc(c).replace(/\n/g,'<br>')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:b.kind==='heading'?`<h4>${esc(b.text)}</h4>`:`<p>${esc(b.text).replace(/\n/g,'<br>')}</p>`).join('')}</div>`;}
function requirements(){return head('The requirements, made navigable.','STE-PRD-001 · Revision 1.0 · Source-derived requirements, not implementation status.',btn('About this prototype','about','','','info'))+tabs([['lifecycle','26-stage lifecycle'],['modes','Accounting modes'],['architecture','Architecture boundaries'],['source','Original requirements']],'requirementTab')+(ui.requirementTab==='lifecycle'?`<div class="banner">${icon('flow')}<p>Explore any stage to read its required inputs, optional steps, review responsibilities, transformations and exit conditions. Accounting and audit planning may progress in parallel.</p></div><div class="lifecycle-grid">${PRD.lifecycle.map(l=>`<button class="lifecycle-card" data-action="lifecycle-detail" data-id="${l.id}"><span class="eyebrow">${l.id}</span><h4>${esc(l.title)}</h4><span class="caption">Read stage requirements ${icon('arrow')}</span></button>`).join('')}</div><div class="panel panel-pad mt24"><h3>The cycle continues</h3><div class="service-track mt16"><span>Archive</span>${icon('arrow')}<span>Annual change review</span>${icon('arrow')}<span>Human continuance</span>${icon('arrow')}<span>New engagement</span>${icon('refresh')}</div><p class="sub mt12">Alternative path: authorized suspension → termination → scoped handover → access revocation → retained evidence.</p></div>`:ui.requirementTab==='modes'?`<div class="grid3"><div class="mode-card"><span class="tag blue">MODE 01</span><h3 class="mt16">Managed bookkeeping</h3><p>Approved source transactions → reviewed journals → entity ledger → trial balance. One posting authority per book. Shown as a requirement, not implemented in this prototype.</p></div><div class="mode-card"><span class="tag green">MODE 02</span><h3 class="mt16">External books / audit workspace</h3><p>External trial balance + approved reporting adjustments → adjusted reporting TB. This is the interactive accounting scenario in the demo.</p></div><div class="mode-card"><span class="tag purple">MODE 03</span><h3 class="mt16">Reporting-only / advisory</h3><p>Validated financial datasets → mappings, models and deliverables. No operational ledger posting unless separately contracted.</p></div></div>${note('The firm’s fee ledger is separate from client books. A professional-fee invoice must never become client income simply because the CRM client is selected.').replace('class="banner ','class="banner mt24 ')}`:ui.requirementTab==='architecture'?`<div class="panel panel-pad"><div class="architecture-row"><div class="architecture-node"><h3>Staff workspace</h3><p>Practice and professional responsibilities</p></div><div class="architecture-node"><h3>Client portal</h3><p>Requests, accounts approval and published deliverables</p></div></div><div class="architecture-arrow">↓</div><div class="architecture-row"><div class="architecture-node"><h3>Scoped identity & authorized commands</h3><p>Client · legal entity · engagement · period · role · revision</p></div></div><div class="architecture-arrow">↓</div><div class="architecture-row"><div class="architecture-node"><h3>Practice lifecycle</h3><p>CRM · acceptance · continuance · billing</p></div><div class="architecture-node"><h3>Accounting production</h3><p>Sources · mappings · journals · statements</p></div><div class="architecture-node"><h3>Professional delivery</h3><p>Workpapers · review · approvals · reports</p></div></div><div class="architecture-arrow">↓</div><div class="architecture-row"><div class="architecture-node"><h3>Versioned data & evidence</h3><p>Relational records · private documents · durable outbox · retained decisions</p></div></div></div><div class="grid2 mt20"><div class="requirements-note"><b>Source PRD architecture</b><br>ARC-01 specifies Perfex CRM / PHP / CodeIgniter / MySQL. Those are preserved in the source reference below, not silently replaced.</div><div class="requirements-note"><b>This deliverable</b><br>A standalone HTML/CSS/JavaScript product visualization. It does not implement Perfex, the AuditSphere .NET backend, or Microsoft services. Screen behavior demonstrates business intent only.</div></div><div class="panel panel-pad mt20"><h3>Production integrations are not connected</h3><div class="row wrap mt16">${['Microsoft Entra ID','SharePoint / Graph','Word / Excel','Purview records','Signing','Filing providers'].map(p=>`<span class="tag gray">${p} · not connected</span>`).join('')}</div></div>`:`<div class="toolbar"><div class="input-search" style="max-width:470px">${icon('search')}<input class="input" id="reference-search" value="${esc(ui.referenceSearch)}" placeholder="Search original sections and requirement text" aria-label="Search original requirements"></div><span class="tag gray">27 source sections</span></div>${PRD.sections.filter(s=>(s.title+JSON.stringify(s.blocks)).toLowerCase().includes(ui.referenceSearch.toLowerCase())).map(s=>`<details class="ref-details"><summary><span class="tag green">§${s.id}</span>${esc(s.title.replace(/^\d+\.\s*/,''))}</summary>${sourceBlocks(s.blocks)}</details>`).join('')}`)+footer();}
