const ROLE_ROUTES={
 overview:['My workspace','grid'],acquisition:['Acquisition & proposals','target'], 'client-summary':['Client relationships','users'],intake:['Onboarding cases','checkboard'],invitations:['Invitation requests','send'],compliance:['Restricted compliance','shield'],acceptance:['Acceptance decisions','shield'],clients:['Client portfolio','users'],engagements:['Engagements','brief'],team:['Team & deadlines','calendar'],documents:['Documents & PBC','folder'],accounting:['Accounting workbench','calculator'],audit:['Audit workpapers','checkboard'],reviews:['Review desk','message'],quality:['Independent EQR','shield'],delivery:['Report release','archive'],continuance:['Annual continuance','refresh'],renewal:['Renewal coordination','refresh'],portal:['Client home','globe'],'client-team':['Contacts & access','users'],'client-requests':['Document requests','upload'],'client-approvals':['Management approvals','checkcircle'],'client-deliverables':['Published deliverables','file'],billing:['Invoices & receipts','receipt'],'commercial-review':['Commercial review','receipt'],'commercial-requests':['Commercial requests','receipt'],records:['Records & holds','archive'],handover:['Controlled handover','folder'],administration:['User administration','users'],'access-requests':['Access requests','lock'],operations:['Integration & operations','settings'],'my-time':['My time entries','clock'],services:['Service catalogue','layers'],'role-guide':['All 14 role views','users'],privileges:['Privileges & boundaries','shield'],requirements:['Requirements reference','book']};
knownRoutes.splice(0,knownRoutes.length,...Object.keys(ROLE_ROUTES));
const initialRoleRoute=location.hash.slice(1);
if(ROLE_ROUTES[initialRoleRoute])ui.route=initialRoleRoute;
let roleUi={group:'All',selectedRole:null};
function ensurePbcRequest(p,e){
 if(!p)return false;
 let changed=false;
 const client=e?C(e.client):C();
 if(!p.description){p.description=p.title||'Requested supporting information';changed=true;}
 if(!p.requestedBy){p.requestedBy=e?.manager||'Layla Rahman';changed=true;}
 if(!p.requestedAt){p.requestedAt=DEMO_DATE+'T08:30:00.000Z';changed=true;}
 if(!p.requestLink){p.requestLink='#client-requests';changed=true;}
 if(!p.email||typeof p.email!=='object'){
  p.email={status:'Prepared for demo delivery — not sent',to:p.owner||client?.contact||'Client contact',subject:'AuditSphere file request: '+p.title,link:p.requestLink};
  changed=true;
 }else{
  if(!p.email.status){p.email.status='Prepared for demo delivery — not sent';changed=true;}
  if(!p.email.to){p.email.to=p.owner||client?.contact||'Client contact';changed=true;}
  if(!p.email.subject){p.email.subject='AuditSphere file request: '+p.title;changed=true;}
  if(!p.email.link){p.email.link=p.requestLink;changed=true;}
 }
 if(!Array.isArray(p.thread)){p.thread=[];changed=true;}
 if(!p.thread.length){
  p.thread.push({id:p.id+'-REQUEST',kind:'request',author:p.requestedBy,role:'staff',text:p.description,time:p.requestedAt});
  p.thread.push({id:p.id+'-EMAIL',kind:'email',author:'AuditSphere demo notification',role:'system',text:'Email preview prepared for '+(p.email.to||'the client')+' with a portal upload link.',time:p.requestedAt});
  changed=true;
 }
 if(!Array.isArray(p.sharedFiles)){p.sharedFiles=[];changed=true;}
 if(p.file){
  const version=p.version||1,uploadedBy=p.lastUploader||p.contributor||p.owner||'Client contact',uploadedAt=p.updatedAt||p.requestedAt;
  if(!p.sharedFiles.some(f=>f.version===version&&f.name===p.file)){
   p.sharedFiles.push({id:p.id+'-FILE-'+version,name:p.file,version,size:p.size||0,sha:p.sha||null,uploadedBy,uploadedAt,source:'Existing synthetic record'});
   changed=true;
  }
  if(!p.thread.some(entry=>entry.kind==='file'&&entry.file===p.file&&entry.version===version)){
   p.thread.push({id:p.id+'-FILE-EVENT-'+version,kind:'file',author:uploadedBy,role:'client_finance',text:'Shared file: '+p.file,time:uploadedAt,file:p.file,version});
   changed=true;
  }
 }
 return changed;
}
function initRoleState(){
 if(!ROLES[state.role])state.role='manager';
 if(!state.roleViews){
  state.roleViews={schema:2,cases:[{id:'CASE-001',client:'CL-001',checks:[true,true,true,true],stage:'Accepted',preparedBy:'Hana Ali',compliance:'Recommend acceptance',comment:'Pre-existing synthetic acceptance used by the workflow demo.',reviewedBy:'Yusuf Ahmed',decisionBy:'Daniel James',history:[]},{id:'CASE-003',client:'CL-003',checks:[true,false,true,false],stage:'Collecting',preparedBy:'Hana Ali',compliance:null,comment:'',history:[]}],tasks:[
   {id:'TASK-001',eng:'ENG-26001',title:'Update asset evidence and respond to review',owner:'preparer',due:'2026-09-23',route:'reviews'},
   {id:'TASK-002',eng:'ENG-26001',title:'Independently review fixed-asset submission',owner:'reviewer',due:'2026-09-24',route:'reviews'},
   {id:'TASK-003',eng:'ENG-26001',title:'Complete significant matters and file consistency',owner:'manager',due:'2026-09-25',route:'reviews'},
   {id:'TASK-004',eng:'ENG-26001',title:'Review the final reporting candidate',owner:'partner',due:'2026-09-28',route:'delivery'},
   {id:'TASK-005',eng:'ENG-26001',title:'Evaluate independent quality-review concerns',owner:'eqr',due:'2026-09-27',route:'quality'}
  ],proposals:[{id:'PROP-001',lead:'LD-002',title:'Summit Engineering · audit proposal',amount:1400000,preparedBy:'Mira Thomas',state:'Draft',note:'Subject to professional acceptance and signed terms.',revision:1}],accessRequests:[{id:'ACCESS-001',name:'Samir Hassan',role:'client_finance',client:'CL-001',state:'Pending verification',requestedBy:'Amal Nasser',reason:'Assist with requested bank statements.'}],users:Object.entries(ROLES).map(([id,r])=>({id,name:r.name,label:r.label,status:'Active'})),eqr:{eligible:false,concerns:[{id:'EQR-001',title:'Evaluate the depreciation judgment and corroboration',status:'Open',response:'',disposition:''}],history:[]},holds:{},handover:[],events:[],commercial:[],representations:{},queries:[],acknowledgements:{},draftChanges:[]};
 }
 state.times.forEach(t=>{if(!t.status)t.status='Submitted';});
 for(const inv of state.invoices){if(inv.status!=='Draft'&&!inv.commercialApproval)inv.commercialApproval={by:'Layla Rahman',basis:'Synthetic prior approval'};if(!inv.preparedBy)inv.preparedBy='Leila Hassan';}
 for(const e of state.engagements){e.pbc.forEach((p,i)=>{if(!p.contributor)p.contributor='Rami Nasser';ensurePbcRequest(p,e);});}
}
const rv=()=>state.roleViews;
const isClientRole=()=>ROLES[state.role].group==='Client';
function roleEnabled(){return rv().users.find(x=>x.id===state.role)?.status!=='Disabled';}
function permission(key,role=state.role){return !!ROLE_PERMISSIONS.find(p=>p.id===key)?.roles.includes(role);}
function visibleEngagements(){return state.engagements.filter(e=>ROLES[state.role].demoClients.includes(e.client));}
function visibleClients(){return state.clients.filter(c=>ROLES[state.role].demoClients.includes(c.id));}
function visibleInvoices(){return state.invoices.filter(i=>ROLES[state.role].demoClients.includes(i.client));}
function routeAllowed(route){return ROLES[state.role].routes.includes(route)&& (roleEnabled()||['overview','role-guide','privileges','requirements'].includes(route));}
function authorizedEng(id){return visibleEngagements().some(e=>e.id===id);}
function ensureContext(){const v=visibleEngagements();if(v.length&&!v.some(e=>e.id===state.selected))state.selected=v[0].id;}
function scopedView(fn){const raw=state;const role=ROLES[state.role];const engagements=visibleEngagements(),clients=visibleClients();const ids=new Set(engagements.map(e=>e.id));state={...state,engagements,clients,invoices:visibleInvoices(),times:state.times.filter(t=>ids.has(t.eng)),events:state.events.filter(ev=>ids.has(ev.ref)),leads:['relationship','manager','partner'].includes(state.role)?state.leads:[]};try{return fn();}finally{state=raw;}}
function addRoleEvent(text,scope=null){rv().events.unshift({text,role:state.role,actor:actor().name,scope,time:new Date().toISOString()});rv().events=rv().events.slice(0,120);save();}
function demoStatus(s){return badge(s,/not connected|pending|collecting|draft|hold|open|unverified/i.test(s)?'amber':/denied|rejected|disabled|blocked/i.test(s)?'red':/accepted|cleared|approved|complete|active|issued|recorded/i.test(s)?'green':'blue');}
function roleScope(){return `<div class="role-scope">${icon('lock')}<div><b>Visibility for ${esc(actor().label)}</b><br>${esc(ROLES[state.role].scope)}</div></div>`;}
function roleList(items,denied=false){return `<ul class="allowed-list ${denied?'denied':''}">${items.map(s=>`<li>${icon(denied?'close':'check')}<span>${esc(s)}</span></li>`).join('')}</ul>`;}
function queuePanel(title,subtitle,items){return panel(title,subtitle,items.length?`<div class="tablewrap"><table class="queue-table"><thead><tr><th>Work item</th><th>Status / due</th><th>Next action</th></tr></thead><tbody>${items.map(x=>`<tr><td><div class="queue-title">${esc(x.title)}</div><div class="queue-meta">${esc(x.meta||'Assigned synthetic record')}</div></td><td>${demoStatus(x.status||'Pending')}<div class="queue-meta">${esc(x.due||'No deadline recorded')}</div></td><td>${x.action?btn(x.label||'Open',x.action,'sm',x.extra||'','arrow'):linkBtn(x.label||'Open',x.route||'overview','sm')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No items in this role’s current scope.</div>');}
function personalQueue(){const r=state.role,e=visibleEngagements()[0];
 if(['preparer','reviewer','manager','partner','eqr'].includes(r))return rv().tasks.filter(t=>t.owner===r&&authorizedEng(t.eng)).map(t=>({title:t.title,meta:t.eng+' · '+actor().label,status:'Awaiting action',due:shortDate(t.due),route:t.route}));
 if(r==='relationship')return state.leads.map(l=>({title:l.name,meta:l.id+' · '+l.service,status:l.stage,route:'acquisition'}));
 if(r==='onboarding'||r==='compliance')return rv().cases.filter(c=>ROLES[r].demoClients.includes(c.client)).map(c=>({title:state.clients.find(x=>x.id===c.client)?.name,meta:c.id,status:c.stage,route:r==='compliance'?'compliance':'intake'}));
 if(r==='client_admin')return [{title:'Verify contact nominations and request ownership',meta:'Example Trading Entity only',status:rv().accessRequests.filter(x=>x.client==='CL-001'&&x.state!=='Approved in demo').length+' pending',route:'client-team'},...e.pbc.slice(0,2).map(p=>({title:p.title,meta:p.contributor,status:p.status,due:shortDate(p.due),route:'client-requests'}))];
 if(r==='client_finance')return e.pbc.filter(p=>p.contributor===actor().name).map(p=>({title:p.title,meta:p.id+' · '+e.id,status:p.status,due:shortDate(p.due),action:'pbc-detail',extra:`data-id="${p.id}"`}));
 if(r==='client')return [{title:'Review management accounts',meta:'Presented version only; not the audit opinion',status:isCurrent('client',e)?'Approved':'Awaiting reviewed package',route:'client-approvals'},{title:'Confirm management representations',meta:'Separate responsibility statement',status:rv().representations[e.id]?.generation===e.generation?'Recorded':'Pending',route:'client-approvals'}];
 if(r==='billing')return visibleInvoices().map(i=>({title:i.id,meta:state.clients.find(c=>c.id===i.client)?.name,status:i.status,due:shortDate(i.due),action:'invoice',extra:`data-id="${i.id}"`}));
 if(r==='records')return visibleEngagements().flatMap(e=>e.releases.map(r=>({title:r.id+' · '+e.id,meta:'Preserved issued version '+r.revision,status:r.delivered?'Ready for assembly':'Delivery pending',route:'records'}))).concat([{title:'Prepare controlled handover or disposition',meta:'No destructive action is performed',status:'Approval required',route:'handover'}]);
 return [{title:'Pending client access verification',meta:'No live directory connection',status:rv().accessRequests.filter(r=>r.state==='Pending verification').length+' pending',route:'access-requests'},{title:'Review integration and recovery configuration',meta:'All provider connections are disabled',status:'Not connected',route:'operations'}];
}
function roleMetrics(){const r=state.role,v=visibleEngagements(),q=personalQueue();
 const base=[['My work items',q.length,'Role-specific queue','checkboard'],['Authorized entities',visibleClients().length,'Explicit demo assignment','users'],['Role activities',ROLE_PERMISSIONS.filter(p=>p.roles.includes(r)).length,'Always subject to scope and state','shield'],['External connections',0,'No live providers connected','cloud']];
 if(r==='client_finance'){base[0]=['Assigned requests',v[0].pbc.filter(p=>p.contributor===actor().name).length,'Only your assigned requests','folder'];base[2]=['Awaiting evidence',v[0].pbc.filter(p=>p.contributor===actor().name&&p.status!=='Accepted').length,'Upload is not acceptance','upload'];}
 if(r==='client'){base[0]=['Management decisions',3,'Terms, adjustments, accounts','checkcircle'];base[2]=['Current account approval',isCurrent('client',v[0])?'Yes':'Pending','Exact package version','file'];}
 if(r==='billing'){base[0]=['Outstanding fees',cash(visibleInvoices().reduce((s,i)=>s+i.amount-i.paid,0)),'Firm books only','receipt'];base[2]=['Draft invoices',visibleInvoices().filter(i=>i.status==='Draft').length,'Independent review first','file'];}
 if(r==='admin'){base[1]=['Demo personas',14,'No real user accounts','users'];base[2]=['Professional powers',0,'Technical access is not sign-off','lock'];}
 return `<div class="metric-grid">${base.map((m,i)=>metric(...m,['','purple','amber','blue'][i])).join('')}</div>`;
}
function roleHome(){const r=ROLES[state.role];if(!roleEnabled())return head('Access suspended in this simulation','This persona was disabled by the simulated system administrator.')+note('Business actions are disabled. Switch to System administrator to review the demo user state. No Microsoft identity or real account was changed.','red')+linkBtn('Inspect role boundaries','privileges');return head(r.home,'Role-specific view · STE-PRD-001 · synthetic demonstration',btn('Browse all roles','r-role-directory','soft','','users'))+`<section class="role-banner ${isClientRole()?'client-hero':''}"><div><div class="eyebrow">${esc(r.group)} / ${esc(r.label)}</div><h2>${esc(r.tagline)}</h2><p>Welcome, ${esc(r.name)}. Your navigation, records and available decisions reflect this selected persona.</p></div>${btn('View my privileges','r-my-privileges','','','shield')}</section>`+roleMetrics()+roleScope()+`<div class="grid-main"><div class="stack">${queuePanel('Your next actions','A task does not grant approval authority.',personalQueue())}${panel('Features in this role','Proposed screen design derived from the source responsibilities.',`<div class="panel-pad" style="padding-top:0"><ul class="feature-list">${r.features.map(f=>`<li>${icon('arrow')}<span>${esc(f)}</span></li>`).join('')}</ul></div>`)}</div><div class="stack">${panel('What you may do','Within assigned scope and required gates.',`<div class="panel-pad" style="padding-top:0">${roleList(r.can)}</div>`)}${panel('Not permitted','Role switching is a demo tool, not real authorization.',`<div class="panel-pad" style="padding-top:0">${roleList(r.cannot,true)}</div>`)}<div class="panel panel-pad"><span class="eyebrow">NEXT HANDOFF</span><p class="small mt12">${esc(r.handoff)}</p><p class="policy-footnote">Source: ${esc(r.refs.join(' · '))}. Detailed navigation and default grants are proposed UI choices; firm policy must approve production privileges.</p></div></div></div>`+footer('§2 · GOV-01–04 · §21');}
function roleDirectory(){const groups=['All','Commercial','Professional','Client','Operations'];const list=Object.entries(ROLES).filter(([k,r])=>roleUi.group==='All'||r.group===roleUi.group);return head('Every role. One connected practice.','Explore all 14 source roles and their separate responsibilities.',btn('Download role catalogue','r-export-catalog','soft','','download'))+note('Design explorer only. The role switcher lets a presenter simulate another user. A production user must never grant themselves access this way.','amber')+`<div class="profile-tabs">${groups.map(g=>`<button data-action="r-filter-group" data-group="${g}" class="${roleUi.group===g?'active':''}">${g}${g==='All'?' · 14':''}</button>`).join('')}</div><div class="role-card-grid">${list.map(([k,r])=>`<section class="role-card ${k===state.role?'active':''}"><div class="between">${avatar(r.initials,r.group==='Client'?'blue':r.group==='Operations'?'amber':r.group==='Commercial'?'purple':'','square')}<span class="tag gray">${r.group}</span></div><h3>${esc(r.label)}</h3><p>${esc(r.tagline)}</p><small>${r.features.length} feature areas · ${ROLE_PERMISSIONS.filter(p=>p.roles.includes(k)).length} scoped activities</small><div class="row wrap">${btn('Enter role view','r-switch-role','primary sm',`data-role="${k}"`)}${btn('Features & privileges','r-role-detail','sm',`data-role="${k}"`)}</div></section>`).join('')}</div>`+footer('§2.1 · Fourteen source roles');}
function privilegePage(){const r=ROLES[state.role];return head('Privileges are not a hierarchy.','A higher title does not automatically inherit another person’s professional authority.',btn('Export permission matrix','r-export-permissions','soft','','download'))+roleScope()+`<div class="grid2 mb16">${panel('Allowed for '+esc(r.label),'Subject to individual assignment and action prerequisites.',`<div class="panel-pad" style="padding-top:0">${roleList(r.can)}</div>`)}${panel('Explicit boundaries','These restrictions are not removable by completing a task.',`<div class="panel-pad" style="padding-top:0">${roleList(r.cannot,true)}</div>`)}</div>`+note('The matrix is a proposed least-privilege UI policy derived from STE-PRD-001. “Scoped” is eligibility, not an unconditional grant; read each condition. The frontend simulates selected actions only. Backend enforcement is not implemented.')+panel('Activity × role matrix','44 defined activity families; scroll horizontally to compare all fourteen roles.',`<div class="tablewrap"><table class="priv-table"><thead><tr><th>Activity and condition</th>${Object.values(ROLES).map(r=>`<th>${esc(r.label)}</th>`).join('')}</tr></thead><tbody>${ROLE_PERMISSIONS.map(p=>`<tr><td><b>${esc(p.label)}</b><div class="action-note">${esc(p.condition)}</div></td>${Object.keys(ROLES).map(k=>`<td class="${p.roles.includes(k)?'priv-yes':'priv-no'}">${p.roles.includes(k)?'Scoped':'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)+footer('§2 · §5 · LC-01–26');}
function safeClientSummary(){return head('Client relationships','Commercial/factual summaries only. Internal financial and review data is not exposed.')+roleScope()+`<div class="grid2">${visibleClients().map(c=>panel(esc(c.name),c.id,`<div class="panel-pad" style="padding-top:0"><div class="info-grid"><div><label>Sector</label><span>${esc(c.industry)}</span></div><div><label>Contact</label><span>${esc(c.contact)}</span></div><div><label>Relationship</label>${demoStatus(c.status)}</div></div><p class="sub mt16">Legal entity, permitted service and contact information. This summary does not reveal TB balances, materiality or private working papers.</p></div>`)).join('')}</div>`+footer('LC-01–09 · Client 360');}
function intakePage(){const list=rv().cases.filter(c=>ROLES[state.role].demoClients.includes(c.client));return head('Collection before verification','Coordinate identity information, supporting documents and signatory requests.')+roleScope()+queuePanel('Onboarding cases','Separate coordinator collection, compliance review and partner acceptance.',list.map(c=>({title:state.clients.find(x=>x.id===c.client)?.name,meta:c.id+' · '+c.checks.filter(Boolean).length+'/4 collection checks',status:c.stage,action:'r-intake-open',extra:`data-id="${c.id}"`,label:'Review collection'})))+`<div class="grid2 mt20">${panel('Invitation requests','Prepared for verification; not automatically active accounts.',`<div class="panel-pad" style="padding-top:0"><p class="small muted">Collect the requested contact, entity and intended role. Verify signatory authority separately from contactability.</p><div class="mt16">${linkBtn('View invitation register','invitations')}</div></div>`)}${panel('No automatic acceptance','Received → checked → decided.',`<div class="panel-pad" style="padding-top:0">${roleList(ROLES.onboarding.cannot,true)}</div>`)}</div>`+footer('LC-04 · LC-06–07');}
function compliancePage(){const list=rv().cases.filter(c=>ROLES[state.role].demoClients.includes(c.client));return head('Restricted compliance review','Keep verification, professional acceptance and client communication separate.')+note('All cases are fictional. No identity, sanctions, PEP or regulatory lookup is performed. No report is transmitted to any authority.','amber')+roleScope()+queuePanel('Assigned review cases','Only explicitly scoped cases appear.',list.map(c=>({title:state.clients.find(x=>x.id===c.client)?.name,meta:c.id+' · prepared by '+c.preparedBy,status:c.stage,action:'r-compliance-open',extra:`data-id="${c.id}"`,label:'Open restricted case'})))+footer('LC-04 · §7 · §17.7');}
function acceptancePage(){return head('Partner acceptance decisions','Compliance clearance supports—but never replaces—the partner’s decision.')+roleScope()+queuePanel('Permitted decision queue','Restricted case detail remains in the compliance workspace.',rv().cases.filter(c=>ROLES[state.role].demoClients.includes(c.client)).map(c=>({title:state.clients.find(x=>x.id===c.client)?.name,meta:c.id+' · clearance outcome: '+(c.compliance||'Not reviewed'),status:c.stage,action:'r-partner-case',extra:`data-id="${c.id}"`,label:'Decide scope'})))+footer('G01–02 · LC-04');}
function teamPage(){return head('Responsibilities and due dates','A task owner is accountable for the next action—not entitled to bypass a review gate.')+roleScope()+queuePanel('Engagement task ownership','Changes are recorded locally with a reason.',rv().tasks.filter(t=>authorizedEng(t.eng)).map(t=>({title:t.title,meta:t.id+' · '+t.eng+' · '+ROLES[t.owner].name,status:'Assigned',due:shortDate(t.due),action:'r-task-open',extra:`data-id="${t.id}"`,label:'Assign / schedule'})))+queuePanel('Time awaiting review','A manager cannot independently approve their own time.',state.times.filter(t=>authorizedEng(t.eng)).map((t,i)=>({title:t.task,meta:t.name+' · '+t.hours+' hours · '+t.eng,status:t.status||'Submitted',action:'r-time-review',extra:`data-index="${state.times.indexOf(t)}"`,label:'Review time'})))+footer('LC-09 · GOV-04 · BIL-01');}
function renewalPage(){return head('Renewal coordination','Prepare the next-period assessment without copying old decisions.')+roleScope()+queuePanel('Relationship follow-up','Partner continuance is a separate decision.',visibleEngagements().map(e=>({title:state.clients.find(c=>c.id===e.client)?.name,meta:e.id+' → FY '+(e.year+1),status:e.annual.decision?'Demo continued':'Reassessment required',action:'r-renewal-note',extra:`data-id="${e.id}"`,label:'Record follow-up'})))+note('Coordination does not renew acceptance. Current evidence, independence, capacity, scope and terms must be reassessed by the authorized roles.')+footer('LC-08 · LC-25');}
