function clientRequests(){const e=E();let list=e.pbc;if(state.role==='client_finance')list=list.filter(p=>p.contributor===actor().name);return head(state.role==='client_admin'?'Coordinate your evidence requests':'Your document requests','A file submission is received first and accepted by the firm separately.')+clientContext()+queuePanel('Prepared by client','Uploads store local metadata/hash only; no document bytes are retained.',list.map(p=>({title:p.title,meta:p.id+' · '+p.contributor,status:p.status,due:shortDate(p.due),action:state.role==='client_admin'?'r-pbc-assign':'pbc-detail',extra:`data-id="${p.id}"`,label:state.role==='client_admin'?'Assign owner':p.file?'View / replace':'Supply evidence'})))+`<div class="panel panel-pad mt20"><h3>Client-facing clarification</h3><p class="sub mt8">Private reviewer discussions are not included in this view.</p><div class="mt16">${btn('Ask a question','client-query','soft','','message')}</div>${rv().queries.filter(q=>q.eng===e.id).map(q=>`<div class="comment"><b class="small">${esc(q.by)}</b><p>${esc(q.text)}</p><p class="caption">Local message only · ${esc(q.status)}</p></div>`).join('')}</div>`+footer('LC-11–12');}
function clientPortalHome(){const e=E();return head(ROLES[state.role].home,'Your authorized client entity, requests and decisions in one place.')+clientContext()+`<div class="role-banner client-hero"><div><div class="eyebrow">${esc(C().name)} / ${esc(actor().label)}</div><h2>Hello, ${esc(actor().name.split(' ')[0])}.</h2><p>${esc(ROLES[state.role].tagline)}</p></div>${btn('View my privileges','r-my-privileges','','','shield')}</div>`+roleMetrics()+`<div class="grid-main"><div class="stack">${queuePanel('Your next actions','Only the information permitted for your client role appears.',personalQueue())}${panel('Engagement team','Ask a factual question; no message is sent outside this browser.',`<div class="panel-pad" style="padding-top:0"><div class="row">${avatar('LR','purple')}<div><h3>Layla Rahman</h3><p class="sub">Engagement manager · synthetic contact</p></div></div><div class="mt16">${btn('Ask the team','client-query','soft sm','','message')}</div></div>`)}</div><div class="stack">${panel('Your boundaries','Your client role does not become an auditor role.',`<div class="panel-pad" style="padding-top:0">${roleList(ROLES[state.role].cannot,true)}</div>`)}${panel('Published material','No private workpapers or firm-only economics.',`<div class="panel-pad" style="padding-top:0"><p class="sub">Final delivered packages appear only after the firm’s release workflow.</p><div class="mt12">${linkBtn('Your deliverables','client-deliverables')}</div></div>`)}</div></div>`+footer('LC-07 · LC-11–12 · LC-22');}
function clientTeam(){return head('Your contacts and responsibilities','Nominate people within your authorized entity. The firm verifies access and signatory authority.',btn('Nominate contact','r-contact-new','primary','','plus'))+clientContext()+queuePanel('Contact requests','Requested roles do not become active permissions automatically.',rv().accessRequests.filter(r=>r.client==='CL-001').map(r=>({title:r.name,meta:r.id+' · '+ROLES[r.role]?.label,status:r.state,action:'r-contact-detail',extra:`data-id="${r.id}"`,label:'View request'})))+`<div class="grid2 mt20">${panel('Permitted nominations','An assigned client administrator cannot widen entity scope.',`<div class="panel-pad" style="padding-top:0">${roleList(['Client finance contributor for existing authorized entities','Client signatory nomination, subject to separate authority verification','Removal request with an effective scope and reason'])}</div>`)}${panel('Never granted here','No staff or professional roles.',`<div class="panel-pad" style="padding-top:0">${roleList(ROLES.client_admin.cannot,true)}</div>`)}</div>`+footer('§2.1 · LC-07 · GOV-04');}
function clientApprovals(){const e=E(),ready=isCurrent('manager');return head('Your management decisions','Approval belongs to the displayed version and your verified authority.')+clientContext()+note('This is a browser simulation. These decisions do not create legally signed documents, post journals, or approve an independent audit opinion.','amber')+`<div class="grid2">${panel('1. Engagement terms','Scope and responsibilities; separate from account approval.',`<div class="panel-pad" style="padding-top:0">${demoStatus(e.terms?'Demo terms recorded':'Pending')}<p class="sub mt12">Entity ${esc(C().name)} · FY ${e.year} · ${esc(e.service)}. Actual terms must identify scope, fees, responsibilities and signatory evidence.</p><div class="mt16">${btn('Review and accept demo terms','r-client-terms','soft sm')}</div></div>`)}${panel('2. Proposed adjustment','Technical review precedes management authorization.',`<div class="panel-pad" style="padding-top:0"><h3>${cash(e.adjustment||50000)} · depreciation</h3><p class="sub mt12">Reporting-layer proposal only. Rejected adjustments remain available for professional evaluation.</p><div class="mt12">${demoStatus(e.journalState)}</div><div class="row wrap mt16">${btn('Review management decision','r-journal-consent','soft sm')}</div></div>`)}${panel('3. Financial statements','Manager-cleared exact draft; no internal review history.',`<div class="panel-pad" style="padding-top:0"><h3>Package v${e.packageRevision}</h3><p class="sub mt12">${ready?'An internally reviewed version is available.':'The firm has not yet made a current manager-reviewed draft available.'}</p><div class="mt12">${demoStatus(isCurrent('client')?'Management approval current':'Management approval pending')}</div><div class="row wrap mt16">${ready?btn('Preview presented draft','preview-report','soft sm','','eye'):''}${btn('Approve management accounts','r-management-approve','primary sm',ready?'':'disabled')}</div></div>`)}${panel('4. Representations','Recorded separately from approving the statements.',`<div class="panel-pad" style="padding-top:0"><p class="sub">Confirm the management responsibilities and statement coverage requested by the engagement team. This demonstration is not a full legal representation letter.</p><div class="mt12">${demoStatus(rv().representations[e.id]?.generation===e.generation?'Current demo attestation':'Not recorded / stale')}</div><div class="mt16">${btn('Record responsibility attestation','r-representation','soft sm')}</div></div>`)}</div>`+footer('LC-06 · LC-17 · LC-22 · GOV-03');}
function clientDeliverables(){const e=E();return head('Your published deliverables','Only delivered client packages—not internal working papers.')+clientContext()+queuePanel('Delivered packages','A delivery acknowledgement is distinct from management approval.',e.releases.filter(r=>r.delivered).map(r=>({title:r.id+' · Financial package v'+r.revision,meta:'FY '+e.year+' · preserved issued preview',status:rv().acknowledgements[e.id+'/'+r.id]?'Acknowledged':'Available',action:'released-preview',extra:`data-id="${r.id}"`,label:'View package'})))+`<div class="row wrap mt16">${e.releases.filter(r=>r.delivered).map(r=>btn('Acknowledge '+r.id,'r-ack-delivery','soft sm',`data-id="${r.id}"`)).join('')}</div>`+panel('Client commercial invoices','Only invoices addressed to this client; no firm margin or staff costs.',`<div class="tablewrap"><table><thead><tr><th>Reference</th><th>Service fee</th><th>Outstanding</th><th>Status</th></tr></thead><tbody>${visibleInvoices().filter(i=>i.client===e.client).map(i=>`<tr><td>${i.id}<div class="cell-sub">${esc(i.description)}</div></td><td>${cash(i.amount)}</td><td>${cash(i.amount-i.paid)}</td><td>${demoStatus(i.status)}</td></tr>`).join('')}</tbody></table></div>`)+footer('LC-24 · BIL-01–04 · UX-03');}
function qualityPage(){const e=E(),q=rv().eqr;return head('Independent engagement quality review','Selected significant judgments and exact versions—not a second preparation team.')+roleScope()+context()+note('Eligibility confirmation and completion are simulated. The production firm must establish independence, competence, scope and appropriate timing.','amber')+`<div class="grid-main"><div class="stack">${panel('Significant judgments selected for review','Read-only evidence summary for this assigned engagement.',`<div class="panel-pad" style="padding-top:0">${e.workpapers.filter(w=>['WP-C1','WP-F1'].includes(w.id)).map(w=>`<div class="borderbox mb16"><div class="between"><h3>${esc(w.title)}</h3>${demoStatus(w.status)}</div><p class="sub mt12">${esc(w.conclusion)}</p><p class="caption mt12">${w.id} · version ${w.version} · source generation ${e.generation}</p></div>`).join('')}</div>`)}${queuePanel('EQR concerns','A team response is not automatic clearance.',q.concerns.map(c=>({title:c.title,meta:c.id,status:c.status,action:'r-eqr-concern',extra:`data-id="${c.id}"`,label:'Evaluate concern'})))}<div class="row">${btn('Raise a concern','r-eqr-add','soft','','plus')}</div></div><div class="stack">${panel('Reviewer eligibility','Must be established outside a simple role selection.',`<div class="panel-pad" style="padding-top:0">${demoStatus(q.eligible?'Demo eligibility recorded':'Eligibility pending')}<div class="mt16">${btn('Record eligibility declaration','r-eqr-eligibility','soft sm')}</div></div>`)}${panel('Completion','Independent completion does not replace the partner.',`<div class="panel-pad" style="padding-top:0"><h3>Package v${e.packageRevision}</h3><div class="mt12">${demoStatus(isCurrent('eqr')?'Current EQR completion':'Not complete / stale')}</div><p class="sub mt12">Open concerns, missing management review or changed dependencies block completion.</p><div class="mt16">${btn('Complete EQR for this version','r-eqr-complete','primary sm')}</div></div>`)}</div></div>`+footer('LC-23 · G09');}
function billingPage(){return head('Firm billing and collections','Client fees belong to the firm’s ledger—not the client reporting TB.',btn('Prepare invoice draft','r-new-invoice','primary','','plus'))+roleScope()+queuePanel('Invoice register','Issue only a reviewed current commercial draft.',visibleInvoices().map(i=>({title:i.id+' · '+cash(i.amount),meta:state.clients.find(c=>c.id===i.client)?.name+' · '+i.description,status:i.status,due:shortDate(i.due),action:'invoice',extra:`data-id="${i.id}"`,label:'Open invoice'})))+`<div class="grid2 mt20">${panel('Commercial separation','Receipts and credits are not professional sign-offs.',`<div class="panel-pad" style="padding-top:0">${roleList(ROLES.billing.cannot,true)}</div>`)}${panel('Credits and exceptions','Separate authorization is required.',`<div class="panel-pad" style="padding-top:0"><p class="sub">Prepare a scoped credit, write-off or refund request. No money is moved and no ledger is posted by this prototype.</p><div class="mt16">${btn('Prepare exception request','r-commercial-new','soft sm')}</div></div>`)}</div>`+footer('BIL-01–04 · DAT-04');}
function commercialReview(){const inv=visibleInvoices().filter(i=>i.status==='Submitted for review');const props=rv().proposals.filter(p=>p.state==='Submitted');return head('Commercial review','Independent fee decisions remain separate from professional report authorization.')+queuePanel('Invoice drafts awaiting review','Only drafts prepared by a different individual are eligible.',inv.map(i=>({title:i.id+' · '+cash(i.amount),meta:i.description+' · '+i.preparedBy,status:i.status,action:'r-review-invoice',extra:`data-id="${i.id}"`,label:'Review'})))+`<div class="mt20">${queuePanel('Proposal drafts','An approved proposal does not accept the client.',props.map(p=>({title:p.title,meta:p.id+' · '+cash(p.amount),status:p.state,action:'r-review-proposal',extra:`data-id="${p.id}"`,label:'Review'})))}</div>`+footer('LC-05 · BIL-02');}
function commercialRequests(){return head('Commercial approval requests','Draft, review and issue remain separately recorded.',btn('New exception request','r-commercial-new','soft','','plus'))+queuePanel('Pending exceptions','Requests do not reduce balances automatically.',rv().commercial.map(c=>({title:c.kind+' · '+c.invoice,meta:c.reason,status:c.state,route:'billing',label:'Invoice register'})))+footer('BIL-02');}
function recordsPage(){const released=visibleEngagements().flatMap(e=>e.releases.map(r=>({e,r})));return head('Records, preservation and holds','Only authorized issued artifacts enter assembly. Working papers are not edited here.')+roleScope()+note('Archive flags and hold records are demonstrations. No retention policy, SharePoint lock or legal hold is actually applied.','amber')+queuePanel('Issued packages','Select a preserved package; never substitute a current working file.',released.map(({e,r})=>({title:r.id+' · '+e.id,meta:'Package v'+r.revision+' · '+(state.clients.find(c=>c.id===e.client)?.name),status:e.archive?.releaseId===r.id?'Demo assembly recorded':r.delivered?'Delivered':'Dispatch pending',action:'r-record-open',extra:`data-eng="${e.id}" data-id="${r.id}"`,label:'Inspect record'})))+`<div class="mt20">${queuePanel('Hold instructions','A hold prevents the simulated disposition request.',visibleEngagements().map(e=>({title:state.clients.find(c=>c.id===e.client)?.name,meta:e.id,status:rv().holds[e.id]?'Active demo hold':'No recorded hold',action:'r-hold-open',extra:`data-eng="${e.id}"`,label:'Hold / disposition'})))}</div>`+footer('LC-25–26 · G11–12');}
function handoverPage(){return head('Controlled handover','Prepare a request with scope, recipient and reason. No files are sent or deleted.',btn('Prepare handover request','r-handover-new','primary','','plus'))+roleScope()+queuePanel('Handover requests','Client-owned records and firm working papers require distinct authority.',rv().handover.filter(h=>authorizedEng(h.eng)).map(h=>({title:h.id+' · '+h.eng,meta:h.recipient+' · '+h.scope,status:h.status,route:'records',label:'Records queue'})))+note('Termination does not authorize immediate deletion. Approval, legal holds, preserved history, access revocation and delivery evidence remain separate obligations.')+footer('LC-26 · G12');}
function invitationPage(){return head('Client invitation requests','Onboarding prepares access; system administration executes only approved scoped instructions.',btn('Prepare invitation request','r-invitation-new','soft','','plus'))+queuePanel('Request register','Pending requests do not grant access.',rv().accessRequests.filter(r=>ROLES[state.role].demoClients.includes(r.client)).map(r=>({title:r.name,meta:r.id+' · '+ROLES[r.role]?.label,status:r.state,action:'r-contact-detail',extra:`data-id="${r.id}"`,label:'View request'})))+footer('LC-07 · GOV-04');}
function adminPage(){return head('Platform user administration','Operate the system without assuming a professional role.')+note('These are synthetic personas, not real directory accounts. Technical administration has no automatic access to financial content or report approval.','amber')+`<div class="metric-grid">${metric('Demo personas',14,'From the 14 source roles','users')}${metric('Pending access',rv().accessRequests.filter(r=>r.state==='Pending verification').length,'Separate authority verification','lock','purple')}${metric('Live directories',0,'Entra is not connected','cloud','blue')}${metric('Professional sign-off',0,'Not granted to administrators','shield','amber')}</div>`+queuePanel('User states','Disabling a demo persona blocks its frontend business actions only.',rv().users.map(u=>({title:u.name,meta:u.label,status:u.status,action:'r-user-open',extra:`data-id="${u.id}"`,label:'Review state'})))+footer('§2.1 · GOV-04 · NFR-02');}
function accessRequestsPage(){return head('Approved access operations','Verify entity scope and signing authority before applying a requested role.')+queuePanel('Pending verification','Client-role nominations never become firm staff grants.',rv().accessRequests.map(r=>({title:r.name,meta:r.id+' · '+ROLES[r.role]?.label,status:r.state,action:'r-access-verify',extra:`data-id="${r.id}"`,label:'Verify request'})))+note('The prototype does not provision accounts or expand the 14 fixed role personas. Approval records here illustrate the handoff only.')+footer('LC-07 · GOV-04 · NFR-01–02');}
function operationsPage(){const integrations=[['Microsoft Entra ID','Interactive identity and session lifecycle'],['SharePoint / Microsoft Graph','Selected-resource documents and permission mapping'],['Microsoft 365','Authenticated human document editing'],['Purview / records','Approved retention and observed record controls'],['Email / signing / filing','Separately authorized channels and artifacts'],['Backup and restore','Cross-store recovery and outward-action quarantine']];return head('Integration and operations','Configuration examples, health placeholders and safe recovery boundaries.',btn('Prepare configuration change','r-config-new','soft','','settings'))+note('Every connection is OFF. A configuration draft does not connect an account, create credentials or make a provider request.','amber')+panel('External capability status','No credentials are requested or stored.',`<div class="config-list">${integrations.map(([name,desc])=>`<div class="config-row"><div><h4>${name}</h4><p>${desc}</p></div>${demoStatus('Not connected')}</div>`).join('')}</div>`)+`<div class="mt20">${queuePanel('Configuration change requests','Separate review and environment-specific authorization are required.',rv().draftChanges.map(c=>({title:c.title,meta:c.reason,status:'Draft — not applied',action:'r-config-detail',extra:`data-id="${c.id}"`,label:'View draft'})))}</div>`+panel('Recovery rule','No blind replay of restored operations.',`<div class="panel-pad" style="padding-top:0"><p class="small muted">Pause outward actions, restore records, reconcile provider state and permissions, verify issued-package identities, then obtain authority before resuming. This screen does not execute a restore.</p></div>`)+footer('ARC-11–13 · NFR-04–09');}
function myTimePage(){return head('My time entries','Record your own effort. Independent review is a separate action.',btn('Record time','log-time','primary','','plus'))+queuePanel('Your submitted time','No self-approval.',state.times.filter(t=>t.name===actor().name&&authorizedEng(t.eng)).map(t=>({title:t.task,meta:t.eng+' · '+t.hours+' hours',status:t.status||'Submitted',due:t.date,route:'overview',label:'My workspace'})))+footer('BIL-01–02');}
let pendingRoleCommand=null;
function textField(id,label,placeholder='',value=''){return `<div class="field mt16"><label for="${id}">${esc(label)} *</label><textarea id="${id}" class="input" placeholder="${esc(placeholder)}">${esc(value)}</textarea></div>`;}
function checkField(id,label,checked=false){return `<label class="checkline"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${esc(label)}</span></label>`;}
function showCommand(title,body,capability,run,label='Record demo action'){pendingRoleCommand={role:state.role,capability,run,selected:state.selected};openModal(title,note('Local demonstration only. No real user, financial transaction, document provider or professional signature is changed.','amber')+body,`${btn('Cancel','close-modal')}${btn(label,'r-confirm','primary')}`,true);}
function reqText(id){return required(id,'Required explanation');}
function checked(id){return !!document.getElementById(id)?.checked;}
function getCase(id){const c=rv().cases.find(x=>x.id===id&&ROLES[state.role].demoClients.includes(x.client));if(!c)throw Error('The requested record is unavailable.');return c;}
function scopedInvoice(id){const i=visibleInvoices().find(x=>x.id===id);if(!i)throw Error('The requested record is unavailable.');return i;}
function requestedContact(id){const r=rv().accessRequests.find(x=>x.id===id);if(!r||(state.role!=='admin'&&!ROLES[state.role].demoClients.includes(r.client)))throw Error('The requested record is unavailable.');return r;}
function roleDetail(k){const r=ROLES[k];if(!r)return;openModal(r.label,`<p class="sub">Source-defined role; proposed screen/grant design.</p><h3 class="mt16">${esc(r.home)}</h3><p class="small mt12">${esc(r.scope)}</p><div class="grid2 mt20"><div><h4 class="mb16">Features and functionalities</h4><ul class="feature-list">${r.features.map(f=>`<li>${icon('arrow')}${esc(f)}</li>`).join('')}</ul><h4 class="mt20 mb16">Eligible actions</h4>${roleList(r.can)}</div><div><h4 class="mb16">Explicit restrictions</h4>${roleList(r.cannot,true)}<h4 class="mt20 mb16">Workflow handoff</h4><p class="small muted">${esc(r.handoff)}</p></div></div><p class="policy-footnote">Source ${esc(r.refs.join(' · '))}. This role has ${ROLE_PERMISSIONS.filter(p=>p.roles.includes(k)).length} proposed scoped activity families. Individual authority, ownership and workflow gates remain mandatory.</p>`,`${btn('Close','close-modal')}${btn('Enter this role view','r-switch-role','primary',`data-role="${k}"`)}`,true);}
function switchRole(k){if(!ROLES[k])return;closeModal();pendingRoleCommand=null;uploadTarget=null;state.role=k;ensureContext();ui.selectedReview=E()?.reviews[0]?.id||'';ui.route='overview';location.hash='overview';save();render();toast('Simulated persona: '+ROLES[k].label+'. No real identity changed.');}
function invoiceDialog(id){const i=scopedInvoice(id);let foot=btn('Close','close-modal');if(i.status==='Draft')foot+=btn('Submit for independent review','r-invoice-submit','primary',`data-id="${i.id}"`);if(i.status==='Approved for issue')foot+=btn('Issue approved demo invoice','invoice-issue','primary',`data-id="${i.id}"`);if(['Issued','Partially paid'].includes(i.status))foot+=btn('Record demo receipt','invoice-receipt','primary',`data-id="${i.id}"`);openModal(i.id+' · firm billing only',note('Synthetic commercial record. Not a payment request, tax invoice or bank receipt.','amber')+`<div class="info-grid"><div><label>Client</label><span>${esc(state.clients.find(c=>c.id===i.client)?.name)}</span></div><div><label>Amount</label><span>${cash(i.amount)}</span></div><div><label>Outstanding</label><span>${cash(i.amount-i.paid)}</span></div></div><p class="sub mt16">${esc(i.description)}</p><div class="mt12">${demoStatus(i.status)}</div><p class="sub mt12">Preparer: ${esc(i.preparedBy)} · Reviewer: ${esc(i.commercialApproval?.by||'Pending')}</p>${['Issued','Partially paid'].includes(i.status)?`<div class="field mt16"><label for="receipt-amount">Demo receipt amount *</label><input class="input" id="receipt-amount" value="${((i.amount-i.paid)/100).toFixed(2)}" inputmode="decimal"></div>`:''}`,foot);}
Object.assign(actions,{
 'r-role-directory':()=>go('role-guide'),'r-my-privileges':()=>go('privileges'),
 'r-filter-group':d=>{roleUi.group=d.group;render();},'r-switch-role':d=>switchRole(d.role),'r-role-detail':d=>roleDetail(d.role),
 'r-export-catalog':()=>download(JSON.stringify({source:'STE-PRD-001 revision 1.0',status:'PROPOSED_ROLE_UI_NOT_PRODUCTION_AUTHORIZATION',roles:ROLES},null,2),'AuditSphere_role_catalogue.json','application/json'),
 'r-export-permissions':()=>download(JSON.stringify({status:'PROPOSED_SCOPED_ACTIVITY_POLICY',permissions:ROLE_PERMISSIONS},null,2),'AuditSphere_role_privileges.json','application/json'),
 'r-confirm':()=>{const c=pendingRoleCommand;if(!c||c.role!==state.role||c.selected!==state.selected||!permission(c.capability)||!roleEnabled())throw Error('This action is unavailable. Reopen it in an authorized role.');c.run();save();pendingRoleCommand=null;closeModal();render();toast('Recorded in the local demonstration only.');},
 'r-intake-open':d=>{const c=getCase(d.id);showCommand(c.id+' · collection checklist',`<p class="small">This is the coordinator’s receipt checklist, not independent verification.</p>${['Entity profile supplied','Ownership/director evidence received','Contact and signatory information received','Scope and terms information collected'].map((label,i)=>checkField('intake-'+i,label,c.checks[i])).join('')}<div class="field mt16"><label for="intake-next">Requested transition</label><select class="input" id="intake-next"><option value="draft">Save collection draft</option><option value="submit">Submit to compliance</option></select></div>`,'intake.write',()=>{const vals=[0,1,2,3].map(i=>checked('intake-'+i));const submit=val('intake-next')==='submit';if(submit&&!vals.every(Boolean))throw Error('Complete all required collection checks before submission.');c.history.push({stage:c.stage,actor:actor().name,time:new Date().toISOString()});c.checks=vals;c.preparedBy=actor().name;c.stage=submit?'Awaiting compliance':'Collecting';c.compliance=null;c.decisionBy=null;addRoleEvent('Intake '+c.id+' '+(submit?'submitted':'saved'),c.client);},'Save / submit checklist');},
 'r-compliance-open':d=>{const c=getCase(d.id);if(!['Awaiting compliance','Compliance hold'].includes(c.stage)){openModal(c.id+' · compliance state',`<p class="small">Current state: ${esc(c.stage)}. An independent review needs a submitted collection file. Existing decisions remain historical.</p>${c.comment?`<p class="sub mt16">${esc(c.comment)}</p>`:''}`,btn('Close','close-modal'));return;}showCommand(c.id+' · restricted disposition',`<p class="small">Prepared by ${esc(c.preparedBy)}. Checks below attest only to the synthetic scenario.</p>${checkField('comp-identity','Identity and ownership evidence reviewed')}${checkField('comp-conflicts','Applicable conflicts and independence concerns considered')}${checkField('comp-open','No unresolved mandatory information/prohibition for an acceptance recommendation')}<div class="field mt16"><label for="comp-decision">Disposition</label><select class="input" id="comp-decision"><option>Compliance hold</option><option>Recommend acceptance</option><option>Recommend decline</option></select></div>${textField('comp-reason','Evidence-based rationale')}`,'compliance.decide',()=>{const decision=val('comp-decision'),reason=reqText('comp-reason');if(c.preparedBy===actor().name)throw Error('An independent checker is required.');if(decision==='Recommend acceptance'&&![checked('comp-identity'),checked('comp-conflicts'),checked('comp-open')].every(Boolean))throw Error('An acceptance recommendation needs all mandatory review checks.');c.compliance=decision;c.comment=reason;c.reviewedBy=actor().name;c.stage=decision==='Compliance hold'?'Compliance hold':'Awaiting partner';c.history.push({decision,reason,actor:actor().name,time:new Date().toISOString()});addRoleEvent('Compliance disposition recorded for '+c.id,c.client);});},
 'r-partner-case':d=>{const c=getCase(d.id);showCommand(c.id+' · partner decision',`<p class="small">Clearance outcome: ${esc(c.compliance||'Pending')}. This view does not disclose restricted case documents.</p><div class="field mt16"><label for="accept-decision">Decision</label><select class="input" id="accept-decision"><option>Hold</option><option>Accept</option><option>Decline</option></select></div>${textField('accept-reason','Decision rationale and permitted scope')}`,'acceptance.decide',()=>{const decision=val('accept-decision'),reason=reqText('accept-reason');if(decision==='Accept'&&(c.compliance!=='Recommend acceptance'||c.stage!=='Awaiting partner'||!c.checks.every(Boolean)))throw Error('Current independent clearances and a submitted partner decision are required.');if(c.preparedBy===actor().name||c.reviewedBy===actor().name)throw Error('Do not self-approve this assessment.');c.stage=decision==='Accept'?'Accepted':decision==='Decline'?'Declined':'Partner hold';c.decisionBy=actor().name;c.history.push({decision,reason,actor:actor().name,time:new Date().toISOString()});state.engagements.filter(e=>e.client===c.client).forEach(e=>{e.acceptance=decision==='Accept';e.generation++;e.candidate=null;});addRoleEvent('Partner '+decision.toLowerCase()+' for '+c.id,c.client);});},
 'r-task-open':d=>{const t=rv().tasks.find(x=>x.id===d.id&&authorizedEng(x.eng));if(!t)throw Error('Unavailable task.');showCommand(t.id+' · ownership and date',`<p class="small">${esc(t.title)} · ${t.eng}</p><div class="field-grid mt16"><div class="field"><label for="task-owner">Responsible existing role</label><select class="input" id="task-owner">${['preparer','reviewer','manager','partner','eqr'].map(k=>`<option value="${k}" ${t.owner===k?'selected':''}>${ROLES[k].name} · ${ROLES[k].label}</option>`).join('')}</select></div><div class="field"><label for="task-due">Due date *</label><input class="input" type="date" id="task-due" value="${t.due}"></div></div>${textField('task-reason','Assignment/change reason')}`,'team.assign',()=>{const owner=val('task-owner'),due=required('task-due','Due date'),reason=reqText('task-reason');const e=state.engagements.find(e=>e.id===t.eng);if(!ROLES[owner].demoClients.includes(e.client))throw Error('The selected individual does not have this engagement scope.');if(owner!==t.owner)throw Error('This task requires its existing professional function. Use a separately verified same-function substitute in production; do not turn a preparer into a reviewer by assignment.');t.due=due;addRoleEvent('Task deadline updated: '+t.id+' · '+reason,e.client);});},
 'r-time-review':d=>{const t=state.times[Number(d.index)];if(!t||!authorizedEng(t.eng))throw Error('Unavailable time entry.');showCommand('Review time entry',`<p class="small">${esc(t.name)} · ${esc(t.task)} · ${t.hours} hours</p>${textField('time-reason','Review explanation')}`,'time.review',()=>{if(t.name===actor().name)throw Error('You cannot independently approve your own time.');t.status='Approved';t.reviewedBy=actor().name;t.reviewReason=reqText('time-reason');addRoleEvent('Time entry reviewed',state.engagements.find(e=>e.id===t.eng).client);});},
 'r-renewal-note':d=>{if(!authorizedEng(d.id))throw Error('Unavailable relationship.');showCommand('Record renewal follow-up',textField('renewal-reason','New-period facts / follow-up needed'),(state.role==='onboarding'?'intake.write':'lead.write'),()=>{rv().events.unshift({text:'Renewal coordination: '+reqText('renewal-reason'),scope:state.engagements.find(e=>e.id===d.id).client,role:state.role,actor:actor().name,time:new Date().toISOString()});});},
 'r-contact-new':()=>nominationDialog('client.nominate'),'r-invitation-new':()=>nominationDialog('intake.write'),
 'r-contact-detail':d=>{const r=requestedContact(d.id);openModal(r.id+' · access request',`<div class="info-grid"><div><label>Name</label><span>${esc(r.name)}</span></div><div><label>Requested role</label><span>${esc(ROLES[r.role].label)}</span></div><div><label>Status</label>${demoStatus(r.state)}</div></div><p class="sub mt16">${esc(r.reason)}</p>${note('A nomination is not active access or verified signatory authority.')}`,btn('Close','close-modal'));},
 'r-pbc-assign':d=>{const p=E().pbc.find(p=>p.id===d.id);if(!p)throw Error('Unavailable request.');showCommand('Assign client contributor',`<p class="small">${esc(p.title)}</p><div class="field mt16"><label for="pbc-owner">Verified contributor for this entity</label><select class="input" id="pbc-owner"><option>Rami Nasser</option></select></div>${textField('pbc-owner-reason','Assignment reason')}`,'pbc.assign',()=>{p.contributor=val('pbc-owner');addRoleEvent('PBC contributor assigned: '+p.id+' · '+reqText('pbc-owner-reason'),E().client);});},
 'r-client-terms':()=>showCommand('Management acceptance of terms',`<p class="small">${esc(C().name)} · ${E().service} · FY ${E().year}</p>${checkField('terms-authority','I represent the verified signatory in this synthetic scenario')}${textField('terms-statement','Acceptance statement')}`,'management.approve',()=>{if(!checked('terms-authority'))throw Error('Confirm the simulated signing authority.');E().terms=true;addRoleEvent('Management terms acceptance: '+reqText('terms-statement'),E().client);}),
 'r-journal-review':()=>showCommand('Independent adjustment review',`<p class="small">Depreciation reporting adjustment: ${cash(E().adjustment)}.</p>${textField('aj-check','Technical review evidence')}`,'journal.review',()=>{if(E().journalState!=='Management pending')throw Error('A current proposed journal is required.');E().journalTechnical={by:actor().name,amount:E().adjustment,revision:E().journalRevision||1,reason:reqText('aj-check')};addRoleEvent('Adjustment technical review recorded',E().client);}),
 'r-journal-consent':()=>showCommand('Management adjustment decision',`<p class="small">Proposed amount ${cash(E().adjustment)}. Existing status: ${esc(E().journalState)}. Approved reporting adjustments do not automatically post into an external or firm ledger.</p><div class="field mt16"><label for="aj-consent">Decision</label><select class="input" id="aj-consent"><option>Accept</option><option>Reject</option></select></div>${textField('aj-consent-reason','Management reason')}`,'journal.consent',()=>{const e=E();if(e.journalState!=='Management pending')throw Error('This journal is not awaiting a new management decision.');if(!e.journalTechnical||e.journalTechnical.amount!==e.adjustment||e.journalTechnical.revision!==(e.journalRevision||1))throw Error('Current independent technical review is required first.');const accepted=val('aj-consent')==='Accept';e.journalState=accepted?'Applied':'Rejected';e.journalManagement={by:actor().name,decision:val('aj-consent'),reason:reqText('aj-consent-reason')};changed('Management '+(accepted?'accepted':'rejected')+' reporting adjustment');}),
 'r-management-approve':()=>showCommand('Approve the exact management package',`<p class="small">Package v${E().packageRevision} · input generation ${E().generation}. This is management’s responsibility, not approval of the auditor’s opinion.</p>${checkField('mgmt-responsible','I accept management responsibility for the presented accounts in this synthetic scenario')}${textField('mgmt-reason','Approval statement')}`,'management.approve',()=>{approvalPrecheck('client');if(!checked('mgmt-responsible'))throw Error('Management responsibility must be confirmed.');E().approvals.client={generation:E().generation,packageRevision:E().packageRevision,actor:actor().name,time:new Date().toISOString(),scope:'client',statement:reqText('mgmt-reason')};addRoleEvent('Management approved exact package v'+E().packageRevision,E().client);}),
 'r-representation':()=>showCommand('Management responsibility attestation',`${checkField('rep-facts','I confirm the factual information and responsibilities requested for this demo package')}${textField('rep-reason','Attestation statement')}`,'management.approve',()=>{if(!isCurrent('manager'))throw Error('A current internally reviewed package must be presented first.');if(!checked('rep-facts'))throw Error('Confirm the responsibility statement.');rv().representations[E().id]={generation:E().generation,revision:E().packageRevision,by:actor().name,text:reqText('rep-reason')};addRoleEvent('Management representation recorded for exact package',E().client);}),
 'r-ack-delivery':d=>{const r=E().releases.find(r=>r.id===d.id&&r.delivered);if(!r)throw Error('No delivered package is available.');rv().acknowledgements[E().id+'/'+r.id]={by:actor().name,time:new Date().toISOString()};addRoleEvent('Client acknowledged delivered package '+r.id,E().client);render();toast('Demo acknowledgement recorded; not account approval.');},
 'r-eqr-eligibility':()=>showCommand('Independent reviewer eligibility',`${checkField('eqr-independent','I am not part of the engagement preparation/partner team in this synthetic scenario')}${checkField('eqr-competent','The assigned scope and competence conditions have been considered for this demonstration')}${textField('eqr-eligibility-reason','Eligibility rationale')}`,'eqr.complete',()=>{if(!checked('eqr-independent')||!checked('eqr-competent'))throw Error('Both eligibility declarations are required.');rv().eqr.eligible=true;rv().eqr.eligibilityReason=reqText('eqr-eligibility-reason');addRoleEvent('Independent EQR eligibility declared in demo',E().client);}),
 'r-eqr-add':()=>showCommand('Raise EQR concern',textField('eqr-title','Significant judgment and required response'),'eqr.complete',()=>{rv().eqr.concerns.push({id:'EQR-'+String(rv().eqr.concerns.length+1).padStart(3,'0'),title:reqText('eqr-title'),status:'Open',response:'',disposition:''});E().approvals.eqr=null;addRoleEvent('New EQR concern raised',E().client);}),
 'r-eqr-concern':d=>{const c=rv().eqr.concerns.find(c=>c.id===d.id);if(!c)throw Error('Unavailable concern.');showCommand(c.id+' · independent evaluation',`<p class="small">${esc(c.title)}</p><p class="sub mt12">Team response: ${esc(c.response||'No response recorded by the engagement manager yet.')}</p><div class="field mt16"><label for="eqr-disposition">Disposition</label><select class="input" id="eqr-disposition"><option>Remain open</option><option>Clear concern</option></select></div>${textField('eqr-review','Independent evaluation')}`,'eqr.complete',()=>{const clear=val('eqr-disposition')==='Clear concern';if(clear&&!c.response)throw Error('The engagement team must respond before independent clearance.');c.status=clear?'Cleared':'Open';c.disposition=reqText('eqr-review');c.reviewedBy=actor().name;addRoleEvent('EQR concern evaluated: '+c.id,E().client);});},
 'r-eqr-response':d=>{const c=rv().eqr.concerns.find(c=>c.id===d.id);if(!c)throw Error('Unavailable concern.');showCommand('Engagement team response',`<p class="small">${esc(c.title)}</p>${textField('eqr-team-response','Team response and evidence references')}`,'manager.approve',()=>{c.response=reqText('eqr-team-response');c.status='Responded';c.respondedBy=actor().name;E().approvals.eqr=null;addRoleEvent('Team responded to EQR concern '+c.id,E().client);});},
 'r-eqr-complete':()=>showCommand('Record independent EQR completion',textField('eqr-complete-reason','Completion rationale for the exact package'),'eqr.complete',()=>{if(!rv().eqr.eligible)throw Error('Reviewer eligibility must be recorded.');if(rv().eqr.concerns.some(c=>c.status!=='Cleared'))throw Error('All significant EQR concerns need independent resolution.');approvalPrecheck('eqr');E().approvals.eqr={generation:E().generation,packageRevision:E().packageRevision,actor:actor().name,time:new Date().toISOString(),scope:'eqr',reason:reqText('eqr-complete-reason')};addRoleEvent('Independent EQR completed for the exact package',E().client);}),
 'r-new-invoice':()=>showCommand('Prepare firm invoice draft',`<div class="field-grid"><div class="field"><label for="new-inv-client">Bill-to entity</label><select class="input" id="new-inv-client">${visibleClients().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="new-inv-amount">Amount QAR *</label><input class="input" id="new-inv-amount" inputmode="decimal" value="1500.00"></div></div>${textField('new-inv-desc','Service and billing basis')}`,'invoice.draft',()=>{const amount=cents(required('new-inv-amount','Amount'));if(amount<=0)throw Error('The invoice amount must be positive.');const client=val('new-inv-client'),eng=state.engagements.find(e=>e.client===client);state.invoices.push({id:'INV-DEMO-'+String(state.invoices.length+1).padStart(3,'0'),client,eng:eng.id,amount,paid:0,description:reqText('new-inv-desc'),status:'Draft',preparedBy:actor().name,due:'2026-10-05'});addRoleEvent('New firm invoice draft prepared',client);}),
 'r-invoice-submit':d=>{const i=scopedInvoice(d.id);if(i.status!=='Draft')throw Error('Only a draft may be submitted.');i.status='Submitted for review';addRoleEvent('Invoice submitted for independent review: '+i.id,i.client);closeModal();render();},
 'r-review-invoice':d=>{const i=scopedInvoice(d.id);showCommand('Review '+i.id,`<p class="small">${esc(i.description)} · ${cash(i.amount)} · prepared by ${esc(i.preparedBy)}</p><div class="field mt16"><label for="inv-decision">Decision</label><select class="input" id="inv-decision"><option>Approve</option><option>Return for rework</option></select></div>${textField('inv-review','Commercial review rationale')}`,'invoice.review',()=>{if(i.preparedBy===actor().name)throw Error('The invoice needs an independent reviewer.');if(i.status!=='Submitted for review')throw Error('The invoice is no longer submitted.');const reason=reqText('inv-review');i.status=val('inv-decision')==='Approve'?'Approved for issue':'Draft';i.commercialApproval=i.status==='Approved for issue'?{by:actor().name,amount:i.amount,reason}:null;addRoleEvent('Commercial review for '+i.id,i.client);});},
 'invoice':d=>invoiceDialog(d.id),
 'invoice-issue':d=>{const i=scopedInvoice(d.id);if(i.status!=='Approved for issue'||!i.commercialApproval||i.commercialApproval.by===i.preparedBy||i.commercialApproval.amount!==i.amount)throw Error('A current independent commercial approval is required.');i.status='Issued';addRoleEvent('Demo firm invoice issued: '+i.id,i.client);closeModal();render();toast('Local issue recorded; no invoice was sent.');},
 'invoice-receipt':d=>{const i=scopedInvoice(d.id);if(!['Issued','Partially paid'].includes(i.status))throw Error('An issued invoice is required.');const n=cents(required('receipt-amount','Receipt amount'));if(n<=0||n>i.amount-i.paid)throw Error('Receipt must be positive and within the outstanding amount.');i.paid+=n;i.status=i.paid===i.amount?'Paid':'Partially paid';addRoleEvent('Synthetic firm receipt allocated: '+i.id,i.client);closeModal();render();toast('No money moved; client TB was unchanged.');},
 'r-commercial-new':()=>showCommand('Prepare billing exception request',`<div class="field-grid"><div class="field"><label for="exc-invoice">Invoice</label><select class="input" id="exc-invoice">${visibleInvoices().map(i=>`<option>${i.id}</option>`).join('')}</select></div><div class="field"><label for="exc-kind">Request</label><select class="input" id="exc-kind"><option>Credit note</option><option>Write-off</option><option>Refund</option></select></div></div>${textField('exc-reason','Reason and approval required')}`,'invoice.draft',()=>{rv().commercial.push({invoice:val('exc-invoice'),kind:val('exc-kind'),reason:reqText('exc-reason'),state:'Pending separate authorization'});addRoleEvent('Billing exception request prepared');}),
 'r-proposal-new':()=>showCommand('Prepare a commercial proposal',`<div class="field"><label for="prop-lead">Assigned lead</label><select class="input" id="prop-lead">${state.leads.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="field mt16"><label for="prop-amount">Illustrative fee QAR *</label><input class="input" id="prop-amount" value="5000.00"></div>${textField('prop-scope','Scope, deliverables and exclusions')}`,'proposal.submit',()=>{const lead=state.leads.find(l=>l.id===val('prop-lead')),amount=cents(required('prop-amount','Fee'));if(amount<=0)throw Error('The fee must be positive.');rv().proposals.push({id:'PROP-'+String(rv().proposals.length+1).padStart(3,'0'),lead:lead.id,title:lead.name+' · '+lead.service,amount,preparedBy:actor().name,state:'Submitted',note:reqText('prop-scope'),revision:1});addRoleEvent('Proposal submitted for independent review');}),
 'r-review-proposal':d=>{const p=rv().proposals.find(p=>p.id===d.id);if(!p)throw Error('Unavailable proposal.');showCommand('Review '+p.id,`<p class="small">${esc(p.title)} · ${cash(p.amount)}</p><p class="sub mt12">${esc(p.note)}</p>${textField('prop-review','Commercial approval rationale')}`,'proposal.review',()=>{if(p.preparedBy===actor().name)throw Error('Independent commercial review is required.');if(p.state!=='Submitted')throw Error('The proposal is not submitted.');p.state='Approved commercially';p.reviewedBy=actor().name;p.reviewReason=reqText('prop-review');addRoleEvent('Commercial proposal approved; professional acceptance remains separate');});}
});
function nominationDialog(cap){showCommand('Nominate a scoped client contact',`<p class="small">${cap==='client.nominate'?'Example Trading Entity only. No sibling or new entity access can be granted here.':'The request remains pending until entity and authority verification.'}</p><div class="field-grid mt16"><div class="field"><label for="contact-name">Synthetic contact name *</label><input class="input" id="contact-name" placeholder="Demo contact"></div><div class="field"><label for="contact-role">Requested client role</label><select class="input" id="contact-role"><option value="client_finance">Client finance contributor</option><option value="client">Client authorized signatory — needs authority evidence</option></select></div></div>${textField('contact-reason','Reason and intended scope')}`,cap,()=>{const name=required('contact-name','Name'),role=val('contact-role');if(!['client_finance','client'].includes(role))throw Error('Only permitted client-role nominations are supported.');rv().accessRequests.push({id:'ACCESS-'+String(rv().accessRequests.length+1).padStart(3,'0'),name,role,client:'CL-001',state:'Pending verification',requestedBy:actor().name,reason:reqText('contact-reason')});addRoleEvent('Client contact nominated for separate verification','CL-001');});}
Object.assign(actions,{
 'r-record-open':d=>{if(!authorizedEng(d.eng))throw Error('Unavailable record.');state.selected=d.eng;const r=E().releases.find(x=>x.id===d.id);if(!r)throw Error('Unavailable record.');openModal(r.id+' · preserved package',`<p class="small">${esc(C().name)} · ${E().id} · package v${r.revision}</p><div class="hash mt16">${esc(r.hash)}</div><p class="sub mt12">The exact package is selected; a new working revision is not substituted.</p><div class="row wrap mt20">${btn('View preserved preview','released-preview','soft sm',`data-id="${r.id}"`)}${btn('Export manifest','release-export','sm',`data-id="${r.id}"`)}</div>${note('All preservation states are local demonstrations. No provider lock is applied.','amber')}`,`${btn('Close','close-modal')}${r.delivered?btn('Assemble demo archive','archive','primary'):btn('Record authorized demo dispatch','demo-deliver','primary',`data-id="${r.id}"`)}`);},
 'r-hold-open':d=>{if(!authorizedEng(d.eng))throw Error('Unavailable record.');state.selected=d.eng;showCommand('Hold / disposition instruction',`<p class="small">${E().id} · ${esc(C().name)}</p><div class="mt12">${demoStatus(rv().holds[E().id]?'Active demo hold':'No recorded hold')}</div><div class="field mt16"><label for="hold-kind">Requested action</label><select class="input" id="hold-kind"><option>Record authorized hold</option><option>Request disposition review</option></select></div>${textField('hold-reason','Instruction reference and reason')}`,'hold.record',()=>{const reason=reqText('hold-reason');if(val('hold-kind')==='Record authorized hold'){rv().holds[E().id]={reason,by:actor().name,time:new Date().toISOString(),state:'SIMULATED_HOLD'};addRoleEvent('Synthetic hold instruction recorded',E().client);}else{if(rv().holds[E().id])throw Error('An active hold blocks disposition. Hold release requires separate authorized evidence and is not simulated here.');rv().handover.push({id:'DISP-'+(rv().handover.length+1),eng:E().id,scope:'Disposition review only — no deletion',recipient:'Authorized records approver',reason,status:'Pending expiry and authority verification'});addRoleEvent('Disposition review requested; no deletion performed',E().client);}});},
 'r-handover-new':()=>showCommand('Prepare controlled handover',`<div class="field"><label for="handover-eng">Authorized engagement</label><select class="input" id="handover-eng">${visibleEngagements().map(e=>`<option value="${e.id}">${e.id} · ${esc(state.clients.find(c=>c.id===e.client)?.name)}</option>`).join('')}</select></div><div class="field mt16"><label for="handover-recipient">Synthetic authorized recipient *</label><input class="input" id="handover-recipient"></div><div class="field mt16"><label for="handover-scope">Requested scope</label><select class="input" id="handover-scope"><option>Client-owned supplied records</option><option>Already delivered client packages</option><option>Restricted workpaper release — separate approval required</option></select></div>${textField('handover-reason','Reason and release authority needed')}`,'handover.request',()=>{const eng=val('handover-eng');if(!authorizedEng(eng))throw Error('Unavailable scope.');rv().handover.push({id:'HAND-'+String(rv().handover.length+1).padStart(3,'0'),eng,recipient:required('handover-recipient','Recipient'),scope:val('handover-scope'),reason:reqText('handover-reason'),status:'Pending independent release approval'});addRoleEvent('Scoped handover request prepared',state.engagements.find(e=>e.id===eng).client);}),
 'r-user-open':d=>{const u=rv().users.find(u=>u.id===d.id);if(!u)throw Error('Unavailable user.');showCommand('Technical user-state request',`<p class="small">${esc(u.name)} · ${esc(u.label)}</p><p class="sub mt12">No role or authority is added by this operation.</p><div class="field mt16"><label for="user-next">Local simulation state</label><select class="input" id="user-next"><option ${u.status==='Disabled'?'selected':''}>Disabled</option><option ${u.status==='Active'?'selected':''}>Active</option></select></div>${textField('user-reason','Authorized instruction / reason')}`,'access.execute',()=>{if(u.id===state.role&&val('user-next')==='Disabled')throw Error('Keep the current demo administrator active to avoid locking out the presenter.');u.status=val('user-next');u.reason=reqText('user-reason');addRoleEvent('Demo user state changed: '+u.id+' · '+u.status);});},
 'r-access-verify':d=>{const r=requestedContact(d.id);showCommand(r.id+' · verify scoped access',`<p class="small">${esc(r.name)} · requested ${esc(ROLES[r.role].label)} · ${r.client}</p>${checkField('access-entity','Entity ownership and requested scope are verified in this synthetic scenario')}${checkField('access-identity','Identity/contact channel and applicable approver instruction are verified')}${r.role==='client'?checkField('access-signatory','Separate management signing authority is verified'):''}${textField('access-reason','Verification evidence reference')}`,'access.execute',()=>{if(!checked('access-entity')||!checked('access-identity')||(r.role==='client'&&!checked('access-signatory')))throw Error('All required identity, scope and signatory checks must be completed.');if(r.requestedBy===actor().name)throw Error('Independent authorization of the requested scope is required.');r.state='Approved in demo';r.verifiedBy=actor().name;r.evidence=reqText('access-reason');addRoleEvent('Access request verified locally: '+r.id);});},
 'r-config-new':()=>showCommand('Prepare technical configuration change',`<div class="field"><label for="config-title">Change title *</label><input class="input" id="config-title" placeholder="Example: staging document repository binding"></div>${textField('config-reason','Purpose and required approval — do not enter secrets')}`,'system.configure',()=>{rv().draftChanges.push({id:'CONFIG-'+(rv().draftChanges.length+1),title:required('config-title','Title'),reason:reqText('config-reason'),state:'Draft'});addRoleEvent('Configuration draft recorded; no integration enabled');}),
 'r-config-detail':d=>{const c=rv().draftChanges.find(c=>c.id===d.id);if(!c)throw Error('Unavailable draft.');openModal(c.id,`<h3>${esc(c.title)}</h3><p class="sub mt16">${esc(c.reason)}</p>${note('Draft only. No credentials, tenant settings or runtime configuration were changed.')}`,btn('Close','close-modal'));}
});
// Keep the existing accounting/review demo, adding narrower projections and explicit role boundaries.
const originalAccounting=pages.accounting,originalReview=pages.reviews,originalAcquisition=pages.acquisition;
pages.accounting=()=>originalAccounting()+(['reviewer'].includes(state.role)?`<div class="panel panel-pad mt20"><h3>Independent adjustment review</h3><p class="sub mt8">The management signatory cannot consent to a new reporting journal before its technical review.</p><div class="mt16">${btn('Review current proposed adjustment','r-journal-review','soft sm')}</div></div>`:'');
pages.reviews=()=>originalReview()+(state.role==='manager'&&E().eqrRequired?`<div class="mt20">${queuePanel('Respond to independent EQR concerns','Only the quality reviewer can clear the concerns.',rv().eqr.concerns.map(c=>({title:c.title,meta:c.id,status:c.status,action:'r-eqr-response',extra:`data-id="${c.id}"`,label:'Respond as manager'})))}</div>`:'');
pages.acquisition=()=>originalAcquisition()+`<div class="panel panel-pad mt20"><div class="between"><div><h3>Versioned commercial proposals</h3><p class="sub">Draft and submit for independent manager review. This does not accept the client.</p></div>${btn('Prepare proposal','r-proposal-new','soft sm')}</div>${rv().proposals.map(p=>`<div class="config-row"><div><h4>${esc(p.title)}</h4><p>${p.id} · ${cash(p.amount)}</p></div>${demoStatus(p.state)}</div>`).join('')}</div>`;
Object.assign(pages,{overview:roleHome,'role-guide':roleDirectory,privileges:privilegePage,'client-summary':safeClientSummary,intake:intakePage,compliance:compliancePage,acceptance:acceptancePage,team:teamPage,renewal:renewalPage,portal:clientPortalHome,'client-team':clientTeam,'client-requests':clientRequests,'client-approvals':clientApprovals,'client-deliverables':clientDeliverables,quality:qualityPage,billing:billingPage,'commercial-review':commercialReview,'commercial-requests':commercialRequests,records:recordsPage,handover:handoverPage,invitations:invitationPage,administration:adminPage,'access-requests':accessRequestsPage,operations:operationsPage,'my-time':myTimePage});
const oldReleaseBlockers=releaseBlockers;
releaseBlockers=function(e=E()){const blockers=oldReleaseBlockers(e);if(isAudit(e)&&!(rv().representations[e.id]?.generation===e.generation&&rv().representations[e.id]?.revision===e.packageRevision))blockers.push('Current management representation is missing');if(e.eqrRequired&&(!rv().eqr.eligible||rv().eqr.concerns.some(c=>c.status!=='Cleared')))blockers.push('Independent EQR eligibility/concern resolution is incomplete');return blockers;};
