actions['log-time']=()=>openModal('Record your work time',`<div class="field-grid"><div class="field full"><label for="time-task">Work description *</label><input id="time-task" class="input"></div><div class="field"><label for="time-hours">Hours *</label><input id="time-hours" class="input" type="number" min="0.1" max="24" step="0.1" value="1"></div><div class="field"><label>Authorized engagement</label><span class="input">${E().id}</span></div></div>`,`${btn('Cancel','close-modal')}${btn('Submit time entry','save-time','primary')}`);
const oldSaveTime=actions['save-time'];actions['save-time']=d=>{oldSaveTime(d);state.times.at(-1).status='Submitted';save();};
const originalPbcModal=pbcModal;pbcModal=function(id){if(!isClientRole())return originalPbcModal(id);const p=E().pbc.find(p=>p.id===id);if(!p||(state.role==='client_finance'&&p.contributor!==actor().name))throw Error('The requested record is unavailable.');openModal(p.id+' · '+p.title,`<div class="between">${demoStatus(p.status)}<span class="caption">Due ${shortDate(p.due)}</span></div><p class="sub mt16">Authorized entity: ${esc(C().name)}. The firm separately reviews evidence adequacy.</p><div class="dropzone mt20">${icon('upload')}<p>${esc(p.file||'Provide the requested synthetic file')}</p><small>5 MiB maximum · metadata and local hash only; bytes are not persisted.</small><div class="row wrap mt16">${btn('Choose local file','pick-document','soft sm',`data-id="${p.id}"`)}${btn('Use built-in sample','sample-upload','sm',`data-id="${p.id}"`)}</div></div>${p.message?`<div class="comment"><h4>Client-facing clarification</h4><p>${esc(p.message)}</p></div>`:''}${p.history?.length?`<p class="caption mt16">${p.history.length} previous submission metadata record(s) retained.</p>`:''}`,btn('Close','close-modal'));};
actions['pbc-detail']=d=>pbcModal(d.id);
const sampleAction=actions['sample-upload'];actions['sample-upload']=d=>{sampleAction(d);const p=E().pbc.find(p=>p.id===d.id);if(p)p.lastUploader=actor().name;save();};
const oldPbcAccept=actions['pbc-accept'];actions['pbc-accept']=d=>{const p=E().pbc.find(p=>p.id===d.id);if(p?.lastUploader===actor().name)throw Error('An independent technical reviewer must accept the submission.');return oldPbcAccept(d);};
// Client consent, technical review and release remain separate even in the demo.
const CLIENT_REQUEST_ROLES=['client_admin','client_finance','client'];
function visibleRequest(id){
 const e=E(),p=e?.pbc.find(x=>x.id===id);
 if(!p)throw Error('The requested file request is unavailable.');
 if(isClientRole()&&!CLIENT_REQUEST_ROLES.includes(state.role))throw Error('The requested client thread is unavailable.');
 if(state.role==='client_finance'&&p.contributor!==actor().name)throw Error('This request is assigned to another client contributor.');
 if(!isClientRole()&&!authorizedEng(e.id))throw Error('The requested engagement is unavailable.');
 const hadThread=Array.isArray(p.thread)&&p.thread.length>0;
 const hadFile=Array.isArray(p.sharedFiles)&&p.sharedFiles.some(f=>f.version===p.version&&f.name===p.file);
 ensurePbcRequest(p,e);
 if(hadThread&&p.file&&!hadFile)recordPbcFile(p,p.file,p.lastUploader||actor().name,p.size,p.sha);
 return p;
}
function requestTime(value){const d=new Date(value);return Number.isNaN(d.valueOf())?'Recorded locally':d.toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});}
function appendPbcThread(p,text,kind='reply',extra={}){
 ensurePbcRequest(p,E());
 const entry={id:p.id+'-THREAD-'+String((p.thread?.length||0)+1).padStart(3,'0'),kind,author:actor().name,role:state.role,text,time:new Date().toISOString(),...extra};
 p.thread.push(entry);
 return entry;
}
function recordPbcFile(p,name,uploader,size=0,sha=null){
 ensurePbcRequest(p,E());
 const version=p.version||1;
 if(!name||p.sharedFiles.some(f=>f.version===version&&f.name===name))return false;
 p.sharedFiles.push({id:p.id+'-FILE-'+version,name,version,size:size||0,sha:sha||null,uploadedBy:uploader||actor().name,uploadedAt:new Date().toISOString(),source:'Client portal upload'});
 appendPbcThread(p,'Shared file: '+name,'file',{file:name});
 addRoleEvent('Client file shared for '+p.id,E().client);
 save();
 return true;
}
function requestTimeline(p,limit){
 const entries=[...(p.thread||[])].sort((a,b)=>new Date(a.time)-new Date(b.time));
 const view=Number.isFinite(limit)?entries.slice(-limit):entries;
 return view.length?`<div class="request-timeline" aria-label="Conversation timeline">${view.map(entry=>{const kind=entry.kind||'reply',label=kind==='email'?'Email notification':kind==='file'?'Shared file':kind==='request'?'File request':'Reply';return `<div class="request-event ${esc(kind)}"><span class="request-event-icon">${icon(kind==='file'?'upload':kind==='email'?'send':kind==='request'?'folder':'message')}</span><div class="request-event-body"><div class="between gap8"><b>${esc(entry.author||'AuditSphere')}</b><span class="caption">${esc(label)} · ${esc(requestTime(entry.time))}</span></div><p>${esc(entry.text||'')}</p></div></div>`;}).join('')}</div>`:'<div class="empty">No conversation events recorded yet.</div>';
}
function requestFiles(p){
 const files=p.sharedFiles||[];
 return files.length?`<div class="request-files" aria-label="Files shared in this request">${files.map(f=>`<div class="attachment-chip"><span class="document-icon ${f.name?.toLowerCase().endsWith('.pdf')?'pdf':''}">${f.name?.toLowerCase().endsWith('.pdf')?'PDF':'FILE'}</span><span><b>${esc(f.name)}</b><small>v${f.version||1} · ${esc(f.uploadedBy||'Client')} · ${f.size?Math.max(1,Math.round(f.size/1024))+' KB':'metadata only'}</small></span></div>`).join('')}</div>`:'<div class="empty">No files have been shared in this request.</div>';
}
function requestEmailMarkup(p,withPortalButton=false){
 const link=withPortalButton?btn('Open upload portal','request-thread','soft sm',`data-id="${p.id}"`,'upload'):`<span class="mono">${esc(p.email?.link||'#client-requests')}</span>`;
 return `<div class="request-email" aria-label="Client email preview"><div class="between"><span class="eyebrow">EMAIL NOTIFICATION · DEMO</span>${demoStatus(p.email?.status||'Prepared — not sent')}</div><div class="email-meta mt12"><div><label>To</label><span>${esc(p.email?.to||p.owner||'Client contact')}</span></div><div><label>Subject</label><span>${esc(p.email?.subject||'AuditSphere file request')}</span></div></div><div class="email-body mt16"><p>Hello,</p><p>${esc(p.requestedBy||'Your engagement team')} requested the following file or information:</p><p><strong>${esc(p.title)}</strong><br>${esc(p.description)}</p><div class="mt12"><label>Portal link</label><div class="between gap8"><span class="mono">${esc(p.email?.link||'#client-requests')}</span>${withPortalButton?link:''}</div></div></div><p class="caption mt12">This browser prototype prepares the email handoff locally; it does not send a real email.</p></div>`;
}
function requestModal(id){
 const e=E(),p=visibleRequest(id),client=C(e.client),canUpload=state.role==='client_finance'&&p.contributor===actor().name;
 const upload=canUpload?`${btn(p.file?'Replace shared file':'Upload file','pick-document','soft sm',`data-id="${p.id}"`,'upload')}${btn('Use built-in sample','sample-upload','sm',`data-id="${p.id}"`)}`:'';
 const review=!isClientRole()?`${btn('Request clarification','pbc-clarify','sm',`data-id="${p.id}"`,'message')}${btn('Accept for request','pbc-accept','primary sm',`data-id="${p.id}"`,'check')}`:'';
 openModal(p.id+' · '+p.title,`${note(isClientRole()?'Client-visible request. Internal reviewer notes remain private.':'Client-facing request thread. Reviewer deliberations remain private.','') }<div class="info-grid"><div><label>Client</label><span>${esc(client?.name||'Authorized client')}</span></div><div><label>Due</label><span>${esc(shortDate(p.due))}</span></div><div><label>Status</label>${demoStatus(p.status)}</div></div><div class="request-description mt20"><span class="eyebrow">REQUEST DESCRIPTION</span><p class="mt8">${esc(p.description)}</p></div><div class="mt20">${requestEmailMarkup(p,isClientRole())}</div><div class="mt20"><div class="between"><div><h3>Shared files</h3><p class="sub">Files and metadata visible to both sides of this request.</p></div>${demoStatus(String((p.sharedFiles||[]).length)+' shared')}</div><div class="mt12">${requestFiles(p)}</div>${upload?`<div class="row wrap mt12">${upload}</div>`:''}</div><div class="mt20"><div class="between"><div><h3>Conversation timeline</h3><p class="sub">Replies are visible to the authorized client and assigned engagement team.</p></div><span class="caption">${p.thread.length} event(s)</span></div><div class="mt12">${requestTimeline(p)}</div></div>`,`${btn('Close','close-modal')}${btn('Reply in thread','request-reply','soft',`data-id="${p.id}"`,'message')}${review}`,true);
}
function requestEmailModal(id){const p=visibleRequest(id);openModal(p.id+' · email preview',requestEmailMarkup(p,false)+note('No external message is sent in this prototype. The client sees the same request and link through the simulated portal.','amber'),`${btn('Close','close-modal')}${btn('Open request thread','request-thread','primary',`data-id="${p.id}"`,'message')}`);}
function requestReplyModal(id){const p=visibleRequest(id);openModal('Reply to '+p.id,`<p class="small">Your reply will be visible to the authorized client and assigned engagement team in the shared timeline.</p><div class="field mt16"><label for="request-reply-text">Message *</label><textarea class="input" id="request-reply-text" placeholder="Write a client-facing reply or clarification."></textarea></div>`,`${btn('Cancel','close-modal')}${btn('Add reply','save-request-reply','primary',`data-id="${p.id}"`,'send')}`);}
function clientRequestsWithThreads(){
 const e=E();let list=e.pbc;if(state.role==='client_finance')list=list.filter(p=>p.contributor===actor().name);
 list.forEach(p=>ensurePbcRequest(p,e));
 return head(state.role==='client_admin'?'Client file requests':'Your file requests & conversations','Every request includes the description, email handoff, shared files and a conversation timeline.')+clientContext()+note('This is a local email-and-portal simulation. Uploads retain metadata and a local hash only; no document bytes are sent or stored.','amber')+`<div class="stack">${list.length?list.map(p=>`<section class="panel request-card"><div class="panel-head"><div><span class="eyebrow">FILE REQUEST · ${esc(p.id)}</span><h2 class="mt8">${esc(p.title)}</h2><p class="sub">Due ${esc(shortDate(p.due))} · Assigned to ${esc(p.contributor||'client contributor')}</p></div>${demoStatus(p.status)}</div><div class="panel-pad" style="padding-top:0"><p class="request-description-text">${esc(p.description)}</p>${requestEmailMarkup(p,true)}<div class="between mt20"><div><h3>Conversation timeline</h3><p class="sub">${p.thread.length} shared event(s)</p></div>${btn('Open full thread','request-thread','soft sm',`data-id="${p.id}"`,'message')}</div><div class="mt12">${requestTimeline(p,3)}</div><div class="between mt20"><div><h3>Shared files</h3><p class="sub">Visible to you and the engagement team.</p></div>${demoStatus(String((p.sharedFiles||[]).length)+' shared')}</div><div class="mt12">${requestFiles(p)}</div></div></section>`).join(''):'<div class="empty panel panel-pad">No file requests are currently assigned to this client scope.</div>'}</div>`+footer('LC-11–12 · Client request communications');
}
function staffRequestThreads(){
 const e=E();return `<div class="mt24">${panel('Client request threads','Create a request, preview the client email handoff, and continue the shared conversation.',`<div class="panel-list">${e.pbc.map(p=>`<div class="list-item"><div><div class="list-item-title">${esc(p.title)}</div><div class="list-item-sub">${p.id} · ${esc(p.owner||'Client contact')} · ${p.thread.length} timeline event(s) · ${(p.sharedFiles||[]).length} shared file(s)</div><p class="sub">${esc(p.description)}</p></div><div class="row wrap">${btn('Open thread','request-thread','soft sm',`data-id="${p.id}"`,'message')}${btn('Email preview','request-email-preview','sm',`data-id="${p.id}"`,'send')}</div></div>`).join('')}</div>`)}</div>`;
}
const originalDocumentsPage=pages.documents;pages.documents=()=>originalDocumentsPage()+staffRequestThreads();
pages['client-requests']=clientRequestsWithThreads;
actions['new-pbc']=()=>openModal('Request a client file',`<div class="field-grid"><div class="field full"><label for="pbc-title">File or information requested *</label><input class="input" id="pbc-title" placeholder="e.g. Year-end inventory listing"></div><div class="field full"><label for="pbc-description">Client-facing description *</label><textarea class="input" id="pbc-description" placeholder="Explain what the client should upload, which period/entity it covers, and any useful context."></textarea></div><div class="field"><label for="pbc-date">Due date *</label><input class="input" id="pbc-date" type="date" value="2026-09-28"></div><div class="field"><label for="pbc-owner">Client email recipient *</label><input class="input" id="pbc-owner" value="${esc(C().contact)}"></div></div><p class="sub mt20">Creates a portal request and a local email preview with an upload link. No external email is sent.</p>`,`${btn('Cancel','close-modal')}${btn('Prepare request & email','save-pbc','primary','', 'send')}`);
actions['save-pbc']=()=>{const title=required('pbc-title','File or information requested'),description=required('pbc-description','Client-facing description'),due=required('pbc-date','Due date'),owner=required('pbc-owner','Client email recipient');if(!/^\d{4}-\d{2}-\d{2}$/.test(due))throw Error('Use a valid date.');const e=E(),p={id:'PBC-'+String(e.pbc.length+1).padStart(2,'0'),title:title.slice(0,150),description:description.slice(0,1000),due,owner:owner.slice(0,120),contributor:'Rami Nasser',category:'Other evidence',status:'Requested',file:'',version:0,requestedBy:actor().name,requestedAt:new Date().toISOString(),requestLink:'#client-requests',sharedFiles:[],thread:[]};ensurePbcRequest(p,e);e.pbc.push(p);addRoleEvent('Client file request prepared: '+p.id,p.id);closeModal();render();toast('Request prepared with a client email preview and upload link. No email was sent.');};
actions['request-thread']=d=>requestModal(d.id);
actions['request-email-preview']=d=>requestEmailModal(d.id);
actions['request-reply']=d=>requestReplyModal(d.id);
actions['save-request-reply']=d=>{const p=visibleRequest(d.id),text=required('request-reply-text','Message').slice(0,2000);appendPbcThread(p,text,'reply');addRoleEvent('Reply added to client request '+p.id,E().client);save();closeModal();render();toast('Reply added to the shared request timeline.');};
const legacySavePbcClarification=actions['save-pbc-clarification'];actions['save-pbc-clarification']=d=>{const p=E().pbc.find(x=>x.id===d.id),result=legacySavePbcClarification(d);if(p){appendPbcThread(p,'Clarification requested: '+p.message,'reply');save();render();}return result;};
const legacyPbcDetail=actions['pbc-detail'];actions['pbc-detail']=d=>requestModal(d.id);
pbcModal=requestModal;
const BASE_ACTION_RULES={
 'new-lead':'lead.write','save-lead':'lead.write','lead-advance':'lead.write','new-eng':'team.assign','save-eng':'team.assign',
 'new-pbc':'pbc.clarify','save-pbc':'pbc.clarify','pick-document':'pbc.upload','sample-upload':'pbc.upload','pbc-accept':'pbc.accept','pbc-clarify':'pbc.clarify','save-pbc-clarification':'pbc.clarify',
 'import-tb':'tb.import','pick-tb':'tb.import','source-change':'tb.import','replace-tb':'tb.import','approve-mapping':'mapping.approve','revise-adjustment':'journal.propose','save-aj':'journal.propose','apply-adjustment':'journal.consent',
 'build-package':'workpaper.write','confirm-supplements':'workpaper.write','clear-rec':'workpaper.review','submit-wp':'workpaper.write','clear-wp':'workpaper.review','save-planning':'partner.approve','save-sample':'workpaper.write',
 'upload-wp-sample':'workpaper.write','wp-pick-workbook':'workpaper.write','wp-pick-evidence':'workpaper.write','wp-sample-evidence':'workpaper.write','wp-unlink-evidence':'workpaper.write','wp-link-pbc-modal':'workpaper.write','wp-link-pbc-confirm':'workpaper.write','save-wp':'workpaper.write','return-wp':'workpaper.review','toggle-wp-applicable':'workpaper.write','wp-add-note':'review.raise','wp-respond-note':'review.respond',
 'respond-note':'review.respond','clear-note':'review.clear','reopen-note':'review.clear','add-note':'review.raise','save-note':'review.raise','portal-approve':'management.approve','record-terms':'management.approve',
 'prepare-release':'release.issue','issue-release':'release.issue','demo-deliver':'release.dispatch','archive':'archive.assemble','invoice-issue':'invoice.issue','invoice-receipt':'receipt.record','log-time':'time.record','save-time':'time.record','continue-client':'continuance.decide','roll-forward':'continuance.decide',
 'r-intake-open':'intake.write','r-compliance-open':'compliance.decide','r-partner-case':'acceptance.decide','r-task-open':'team.assign','r-time-review':'time.review','r-pbc-assign':'pbc.assign','r-client-terms':'management.approve','r-journal-review':'journal.review','r-journal-consent':'journal.consent','r-management-approve':'management.approve','r-representation':'management.approve','r-eqr-eligibility':'eqr.complete','r-eqr-add':'eqr.complete','r-eqr-concern':'eqr.complete','r-eqr-complete':'eqr.complete','r-eqr-response':'manager.approve','r-contact-new':'client.nominate','r-invitation-new':'intake.write','r-new-invoice':'invoice.draft','r-invoice-submit':'invoice.draft','r-review-invoice':'invoice.review','r-commercial-new':'invoice.draft','r-proposal-new':'proposal.submit','r-review-proposal':'proposal.review','r-record-open':'archive.assemble','r-hold-open':'hold.record','r-handover-new':'handover.request','r-user-open':'access.execute','r-access-verify':'access.execute','r-config-new':'system.configure','r-config-detail':'system.configure'};
const GENERIC_ACTIONS=new Set(['menu','close-modal','search','activity','about','reset','confirm-reset','source','service-detail','lifecycle-detail','r-role-directory','r-my-privileges','r-filter-group','r-switch-role','r-role-detail','r-export-catalog','r-export-permissions','tour','tour-requirements','wp-tab','download-wp-template']);
function allowedAction(name,d={}){
 if(GENERIC_ACTIONS.has(name))return true;
 if(!roleEnabled())return false;
 if(name==='r-confirm')return !!pendingRoleCommand&&pendingRoleCommand.role===state.role&&permission(pendingRoleCommand.capability);
 if(BASE_ACTION_RULES[name])return permission(BASE_ACTION_RULES[name]);
 if(name==='r-renewal-note')return ['relationship','onboarding'].includes(state.role);
 if(name==='r-contact-detail')return ['client_admin','onboarding','admin'].includes(state.role);
 if(name==='r-ack-delivery'||name==='client-query'||name==='save-client-query')return isClientRole();
 if(['request-thread','request-reply','save-request-reply'].includes(name))return ['preparer','reviewer','manager','client_admin','client_finance','client'].includes(state.role);
 if(name==='request-email-preview')return ['preparer','reviewer','manager'].includes(state.role);
 if(name==='invoice')return state.role==='billing';
 if(name==='lead-detail')return state.role==='relationship';
 if(name==='package-approve')return state.role===d.key&&permission({manager:'manager.approve',client:'management.approve',partner:'partner.approve',eqr:'eqr.complete'}[d.key]);
 if(['open-reviews','open-approvals'].includes(name))return routeAllowed('reviews');
 if(name==='open-overview')return true;
 if(name==='eng-open')return !isClientRole()&&state.role!=='admin'&&!!d.id&&authorizedEng(d.id);
 if(name==='client-detail')return routeAllowed('clients')&&visibleClients().some(c=>c.id===d.id);
 if(name==='service-for-eng')return routeAllowed('services');
 if(name==='pbc-detail')return ['preparer','reviewer','manager','client_finance'].includes(state.role)&&(!d.id||E().pbc.some(p=>p.id===d.id&&(state.role!=='client_finance'||p.contributor===actor().name)));
 if(['preview-report','export-report','print-report'].includes(name))return permission('financial.read')||(state.role==='client'&&isCurrent('manager'));
 if(['released-preview','released-download'].includes(name))return ['partner','records'].includes(state.role)||(isClientRole()&&E().releases.some(r=>r.id===d.id&&r.delivered));
 if(name==='release-export')return ['partner','records'].includes(state.role);
 if(['tb-template','export-tb','reconciliation','supplements'].includes(name))return permission('financial.read');
 if(['workpaper','planning','sample-result','summary-memo','announcement','report-memo','select-review'].includes(name))return ['preparer','reviewer','manager','partner'].includes(state.role);
 if(name==='offboarding')return ['records','partner'].includes(state.role);
 if(name==='tab')return !isClientRole()&&state.role!=='admin';
 if(name==='tour-accounting')return routeAllowed('accounting');
 return false;
}
const legacyButton=btn;
btn=function(text,action,cls='',extra='',ic=''){const data={};for(const m of extra.matchAll(/data-([\w-]+)="([^"]*)"/g))data[m[1].replace(/-([a-z])/g,(_,c)=>c.toUpperCase())]=m[2];if(!allowedAction(action,data))extra+=' disabled aria-disabled="true" title="Not permitted for this role in the demonstration"';return legacyButton(text,action,cls,extra,ic);};
linkBtn=function(text,route,cls=''){return `<button class="btn ghost ${cls}" data-route="${route}" ${routeAllowed(route)?'':'disabled title="Outside this role’s navigation"'}>${text}${icon('arrow')}</button>`;};
const originalRoleAllowed=roleAllowed;roleAllowed=function(roles){return originalRoleAllowed(roles);};
context=function(){if(isClientRole())return clientContext();const e=E(),list=visibleEngagements();if(!e||!list.length)return '';return `<div class="contextbar"><div class="context-item"><label>Authorized engagement</label><select id="eng-select" aria-label="Selected authorized engagement">${list.map(x=>`<option value="${esc(x.id)}" ${x.id===e.id?'selected':''}>${esc(state.clients.find(c=>c.id===x.client)?.name)} · ${x.year}</option>`).join('')}</select></div><div class="context-item"><label>Service / period</label>${esc(e.service)} · FY ${e.year}</div><div class="context-item"><label>Reporting basis</label>${esc(e.mode)} · QAR</div><div class="context-item"><label>Package</label>v${e.packageRevision} ${badge(e.builtGeneration===e.generation?'Current':'Stale')}</div></div>`;};
go=function(route){if(!routeAllowed(route)){toast('This workspace is not available to the selected role.','warn');ui.route='overview';location.hash='overview';render();return;}closeModal();ui.route=route;location.hash=route;render();window.scrollTo(0,0);};
function filteredEvents(){return rv().events.filter(ev=>{if(isClientRole())return ev.scope==='CL-001'&&['client_admin','client_finance','client'].includes(ev.role);if(state.role==='admin')return ev.role==='admin';if(state.role==='billing')return ['billing','manager'].includes(ev.role)&&/invoice|receipt|commercial|billing|proposal/i.test(ev.text);if(state.role==='compliance')return ev.role==='compliance'&&ROLES[state.role].demoClients.includes(ev.scope);if(ev.role==='compliance'||ev.role==='admin')return false;return ev.role===state.role||(ev.scope&&ROLES[state.role].demoClients.includes(ev.scope));});}
actions.activity=()=>openModal('Your local activity',`<p class="sub mb16">Editable browser history, not a secure audit log.</p>${filteredEvents().map(ev=>`<div class="activity"><div class="activity-dot">${icon('clock')}</div><div><p>${esc(ev.text)}</p><small>${esc(ev.actor)} · ${esc(ev.time)}</small></div></div>`).join('')||'<div class="empty">No visible role activity yet.</div>'}`,btn('Close','close-modal'));
actions.tour=()=>openModal('Explore the complete role handoffs',`<p class="small">Use the top-right simulator to switch among 14 source roles. It is a presentation control, not a real login.</p>${[['1','Commercial → onboarding → compliance → partner','Prepare a proposal, collect CASE-003 evidence, submit for compliance, then obtain a distinct partner decision.'],['2','Client administrator → finance contributor','Nominate a contact, assign a document request, then upload a built-in synthetic sample as the contributor.'],['3','Preparer → senior → manager','Respond to review points, clear them independently, rebuild the package as preparer, then record manager review.'],['4','Client signatory → partner → quality reviewer','Approve the presented accounts, attest representations, respond to EQR concerns as manager, then record EQR as its independent reviewer.'],['5','Partner → records administrator','Issue the frozen demo package, record authorized dispatch, assemble its manifest and demonstrate hold/disposition blocking.'],['6','Billing officer → manager → billing officer','Prepare/submit an invoice, review it independently, then issue and record a bounded synthetic receipt.']].map(([n,t,p])=>`<div class="tour-step"><div class="stepnum">${n}</div><div><h4>${t}</h4><p>${p}</p></div></div>`).join('')}<p class="policy-footnote">System administration is a separate technical view. No role selection grants actual provider access, signs a document or creates a production approval.</p>`,`${btn('Close','close-modal')}${btn('Explore all roles','r-role-directory','primary')}`,true);
actions.about=()=>openModal('AuditSphere · all-role visualization',`<h3>14 source roles · 44 proposed activity families</h3><p class="sub mt16">Source: STE-PRD-001 revision 1.0, §§2 and 21, supported by the lifecycle and approval requirements. Role duties are source-derived; dashboard layouts and narrower default permissions are proposed design decisions.</p><p class="sub mt16">This extends the earlier interactive prototype with role-specific homepages, navigation, record projections, command checks and handoffs. It preserves the original prototype and source documents.</p><p class="sub mt16">No backend, authentication, enforceable multi-user security, secure storage, live Microsoft integration, legal signature, real financial posting, complete methodology or production retention is implemented. Source files and all demo data remain inspectable by anyone who has this HTML. Use synthetic data only.</p>`,btn('Close','close-modal'),true);
updateSearch=function(query){const q=query.toLowerCase();const items=ROLES[state.role].routes.map(route=>({title:ROLE_ROUTES[route][0],sub:'Permitted workspace',route}));if(['preparer','reviewer','manager','partner'].includes(state.role))items.push(...visibleEngagements().map(e=>({title:state.clients.find(c=>c.id===e.client)?.name,sub:e.id,eng:e.id})));const matches=items.filter(x=>(x.title+' '+x.sub).toLowerCase().includes(q)).slice(0,12),target=document.getElementById('search-results');if(target)target.innerHTML=matches.length?matches.map(x=>`<button class="search-result" ${x.route?`data-route="${x.route}"`:`data-action="eng-open" data-id="${x.eng}"`}>${icon(x.route?'grid':'users')}<div><b class="small">${esc(x.title)}</b><small>${esc(x.sub)}</small></div></button>`).join(''):'<div class="empty">No matching records in this role’s scope.</div>';};
render=function(){initRoleState();ensureContext();if(!routeAllowed(ui.route)){ui.route='overview';if(location.hash!=='#overview')history.replaceState(null,'','#overview');}const r=ROLES[state.role],title=ROLE_ROUTES[ui.route]?.[0]||r.home;const main=roleEnabled()?scopedView(()=>pages[ui.route]()):roleHome();const groups=['Commercial','Professional','Client','Operations'];document.getElementById('app').innerHTML=`<div class="mobile-overlay" data-action="menu" id="mobile-overlay"></div><aside class="sidebar" id="sidebar"><div class="brand"><div class="brandmark">${icon('layers')}</div><div class="brandname">Audit<span>Sphere</span></div></div><div class="workspaceselect"><span class="firmavatar">STE</span><span>STE Audit & Accounting<div style="font-size:9px;color:#8daba7;margin-top:1px">${esc(r.group)} workspace</div></span></div><div class="portal-nav-context">${esc(r.label)}<br><span class="role-mini">${isClientRole()?'CLIENT PORTAL':'ROLE-SCOPED WORKSPACE'}</span></div><nav class="side-scroll" aria-label="Role navigation"><div class="nav-label">YOUR WORKSPACE</div>${r.routes.filter(routeAllowed).map((route,i)=>`${route==='role-guide'?'<div class="nav-label">DESIGN REFERENCE</div>':''}<button class="navitem ${route===ui.route?'active':''}" data-route="${route}" ${route===ui.route?'aria-current="page"':''}>${icon(ROLE_ROUTES[route][1])}<span>${route==='overview'?'My dashboard':esc(ROLE_ROUTES[route][0])}</span></button>`).join('')}</nav><div class="side-footer"><div class="side-demo"><strong>14-role interactive visualization</strong>All data is synthetic.<br>No real login or secure access control.</div><button class="navitem" data-action="reset">${icon('refresh')}Reset local demo</button></div></aside><div class="shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="role-breadcrumb">${esc(r.group)} / <b>${esc(title)}</b></div><button class="search-trigger" data-action="search">${icon('search')}Search your workspace<kbd>/</kbd></button></div><div class="topbar-right"><button class="icon-btn" data-action="tour" aria-label="Explore role handoffs">${icon('play')}</button><button class="icon-btn" data-action="activity" aria-label="Your local activity">${icon('bell')}</button><div class="persona">${avatar(r.initials,r.group==='Client'?'blue':'')}<div><label for="role-select">DEMO PERSONA · NOT A LOGIN</label><select id="role-select" aria-label="Switch simulated user role">${groups.map(g=>`<optgroup label="${g}">${Object.entries(ROLES).filter(([k,v])=>v.group===g).map(([k,v])=>`<option value="${k}" ${k===state.role?'selected':''}>${esc(v.label)}</option>`).join('')}</optgroup>`).join('')}</select></div></div></div></header><main class="main" id="main" tabindex="-1">${main}</main></div>`;document.title=`${r.label} · AuditSphere Role Prototype`;};
// A centralized frontend guard keeps the visualization internally consistent.
// It does not protect HTML/localStorage from a user with developer tools.
for(const [name,fn] of Object.entries(actions)){actions[name]=async function(d={}){if(!allowedAction(name,d))throw Error('This action is not permitted for the selected demo role.');if(d.eng&&!authorizedEng(d.eng)&&state.role!=='admin')throw Error('The requested record is unavailable.');return fn(d);};}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!allowedAction(target.dataset.action,target.dataset)){event.preventDefault();event.stopImmediatePropagation();toast('This action is not permitted for this role.','warn');}},true);
document.addEventListener('change',event=>{const t=event.target;if(t.id==='role-select'){event.stopImmediatePropagation();switchRole(t.value);return;}if(t.id==='eng-select'&&!authorizedEng(t.value)){event.stopImmediatePropagation();render();toast('The requested context is unavailable.','warn');return;}if(t.id==='document-picker'&&(typeof uploadTarget!=='undefined'&&uploadTarget?.type?!permission('workpaper.write'):!permission('pbc.upload'))||t.id==='tb-picker'&&!permission('tb.import')){event.stopImmediatePropagation();toast('This upload action is outside the selected role.','warn');return;}if(t.dataset.change==='mapping'&&!permission('mapping.write')||t.dataset.change==='assessment-item'&&!permission('intake.write')||t.dataset.change==='annual'&&state.role!=='partner'){event.stopImmediatePropagation();render();toast('This edit is outside the selected role.','warn');}},true);
const resetAction=actions['confirm-reset'];actions['confirm-reset']=async d=>{await resetAction(d);initRoleState();state.role='manager';render();save();};
// No v1 state is migrated or deleted; v2 uses its own localStorage key.
initRoleState();ensureContext();render();save();
